const LUKE_SECTIONS = {};

LUKE_SECTIONS["1"] = [{"title":"Úvod","range":"Lk 1,1–4","thoughts":[],"verses":[[1,"Mnozí se už pokusili sepsat zprávu o událostech, které se mezi námi naplnily,"],[2,"tak, jak nám je předali ti, kteří je od začátku sami viděli a potom sloužili slovu."],[3,"Proto jsem se i já rozhodl, vznešený Teofile, že všechno od začátku pečlivě prozkoumám a souvisle ti to sepíšu,"],[4,"abys poznal, jak spolehlivé je to, čemu jsi byl vyučován."]]},{"title":"Oznámení narození Jana Křtitele","range":"Lk 1,5–25","thoughts":[],"verses":[[5,"Za vlády judského krále Heroda žil kněz jménem Zachariáš z Abiášovy kněžské skupiny. Jeho žena Alžběta pocházela z rodu Áronova."],[6,"Oba žili před Bohem spravedlivě a věrně se řídili všemi Pánovými přikázáními a ustanoveními."],[7,"Neměli však děti, protože Alžběta byla neplodná, a oba už byli pokročilého věku."],[8,"Jednou, když byla na řadě jeho kněžská skupina, konal Zachariáš před Bohem kněžskou službu."],[9,"Podle kněžského zvyku na něj padl los, aby vstoupil do Pánova chrámu a zapálil kadidlo."],[10,"V době přinášení kadidla se venku modlil celý shromážděný lid."],[11,"Vtom se Zachariášovi ukázal Pánův anděl, který stál po pravé straně kadidlového oltáře."],[12,"Když ho Zachariáš uviděl, polekal se a zmocnil se ho strach."],[13,"Anděl mu však řekl: „Neboj se, Zachariáši. Tvá modlitba byla vyslyšena. Tvá žena Alžběta ti porodí syna a dáš mu jméno Jan."],[14,"Budeš z něj mít radost a veliké potěšení a z jeho narození se bude radovat mnoho lidí."],[15,"Bude totiž veliký před Pánem. Nebude pít víno ani jiný opojný nápoj a už od života své matky bude naplněn Duchem svatým."],[16,"Mnoho Izraelitů obrátí zpět k Pánu, jejich Bohu."],[17,"Půjde před ním v Eliášově duchu a moci. Obrátí srdce otců k dětem a neposlušné přivede k moudrosti spravedlivých. Tak připraví Pánu lid, který bude připraven.“"],[18,"Zachariáš se anděla zeptal: „Podle čeho poznám, že je to pravda? Jsem už starý a také má žena je pokročilého věku.“"],[19,"Anděl mu odpověděl: „Já jsem Gabriel a stojím před Bohem. Byl jsem poslán, abych s tebou mluvil a oznámil ti tuto dobrou zprávu."],[20,"Protože jsi však nevěřil mým slovům, která se ve svůj čas naplní, nebudeš moci mluvit až do dne, kdy se to stane.“"],[21,"Lidé mezitím čekali na Zachariáše a divili se, proč se v chrámu tak dlouho zdržuje."],[22,"Když vyšel ven, nemohl k nim promluvit. Pochopili tedy, že měl v chrámu vidění. Dorozumíval se s nimi jen posunky a zůstal němý."],[23,"Když skončily dny jeho služby, vrátil se domů."],[24,"Brzy potom jeho žena Alžběta otěhotněla. Pět měsíců se držela v ústraní a říkala:"],[25,"„Tohle pro mě udělal Pán. Teď na mě pohlédl a zbavil mě hanby mezi lidmi.“"]]},{"title":"Oznámení narození Ježíše","range":"Lk 1,26–38","thoughts":[],"verses":[[26,"V šestém měsíci poslal Bůh anděla Gabriela do galilejského města Nazaret."],[27,"Poslal ho k panně zasnoubené muži jménem Josef, který pocházel z Davidova rodu. Ta panna se jmenovala Marie."],[28,"Anděl k ní přišel a řekl: „Buď zdráva, ty, které se dostalo veliké milosti. Pán je s tebou.“"],[29,"Marie se nad jeho slovy zarazila a přemýšlela, co má takový pozdrav znamenat."],[30,"Anděl jí řekl: „Neboj se, Marie, protože jsi našla milost u Boha."],[31,"Otěhotníš, porodíš syna a dáš mu jméno Ježíš."],[32,"Bude veliký a bude nazýván Synem Nejvyššího. Pán Bůh mu dá trůn jeho otce Davida."],[33,"Bude navěky kralovat nad Jákobovým rodem a jeho království nebude mít konec.“"],[34,"Marie se anděla zeptala: „Jak se to může stát, když nežiji s mužem?“"],[35,"Anděl jí odpověděl: „Sestoupí na tebe Duch svatý a moc Nejvyššího tě zastíní. Proto také dítě, které se narodí, bude svaté a bude nazýváno Božím Synem."],[36,"Podívej, i tvá příbuzná Alžběta čeká ve svém stáří syna. Ta, o které se říkalo, že je neplodná, je už v šestém měsíci."],[37,"Pro Boha totiž není nic nemožné.“"],[38,"Marie řekla: „Jsem Pánova služebnice. Ať se mi stane podle tvého slova.“ Potom od ní anděl odešel."]]},{"title":"Marie navštěvuje Alžbětu","range":"Lk 1,39–56","thoughts":[],"verses":[[39,"V těch dnech se Marie vydala na cestu a spěchala do jednoho města v judských horách."],[40,"Vešla do Zachariášova domu a pozdravila Alžbětu."],[41,"Jakmile Alžběta uslyšela Mariin pozdrav, dítě v jejím těle se pohnulo radostí a Alžběta byla naplněna Duchem svatým."],[42,"Hlasitě zvolala: „Požehnaná jsi mezi ženami a požehnané je dítě, které nosíš."],[43,"Jak se mi dostalo té cti, že ke mně přichází matka mého Pána?"],[44,"Jakmile jsem zaslechla tvůj pozdrav, dítě v mém těle se radostí pohnulo."],[45,"Blaze té, která uvěřila, že se splní to, co jí Pán řekl.“"],[46,"Marie řekla: „Má duše oslavuje Pána"],[47,"a můj duch se raduje v Bohu, mém Zachránci,"],[48,"protože pohlédl na poníženost své služebnice. Od této chvíle mě budou všechny generace nazývat blahoslavenou,"],[49,"protože Mocný pro mě udělal veliké věci. Jeho jméno je svaté"],[50,"a jeho milosrdenství trvá od generace ke generaci pro ty, kdo před ním mají úctu."],[51,"Svou mocnou paží vykonal veliké věci a rozehnal ty, kdo jsou pyšní ve svých srdcích."],[52,"Mocné sesadil z trůnů a ponížené pozvedl."],[53,"Hladové nasytil dobrými věcmi a bohaté poslal pryč s prázdnou."],[54,"Ujal se Izraele, svého služebníka, a nezapomněl na své milosrdenství,"],[55,"jak slíbil našim otcům, Abrahamovi a jeho potomstvu navěky.“"],[56,"Marie zůstala u Alžběty asi tři měsíce a potom se vrátila domů."]]},{"title":"Narození Jana Křtitele","range":"Lk 1,57–66","thoughts":[],"verses":[[57,"Alžbětě se naplnil čas porodu a porodila syna."],[58,"Její sousedé a příbuzní uslyšeli, jak veliké milosrdenství jí Pán prokázal, a radovali se s ní."],[59,"Osmého dne přišli dítě obřezat a chtěli mu dát jméno Zachariáš po jeho otci."],[60,"Jeho matka však řekla: „Ne. Bude se jmenovat Jan.“"],[61,"Namítli jí: „Vždyť nikdo z tvých příbuzných se tak nejmenuje.“"],[62,"Posunky se tedy ptali jeho otce, jaké jméno chce dítěti dát."],[63,"Zachariáš si vyžádal tabulku a napsal: „Jeho jméno je Jan.“ Všichni se tomu podivili."],[64,"V té chvíli se mu otevřela ústa, jazyk se mu uvolnil a začal mluvit a chválit Boha."],[65,"Všech jejich sousedů se zmocnila posvátná bázeň a po celém judském pohoří se o těchto událostech mluvilo."],[66,"Všichni, kdo o tom slyšeli, si to uchovávali v srdci a říkali si: „Co z toho dítěte asi bude?“ Bylo totiž zřejmé, že Pán je s ním."]]},{"title":"Zachariášův chvalozpěv","range":"Lk 1,67–80","thoughts":[],"verses":[[67,"Jeho otec Zachariáš byl naplněn Duchem svatým a prorokoval:"],[68,"„Požehnaný je Pán, Bůh Izraele, protože přišel ke svému lidu a přinesl mu vykoupení."],[69,"V domě svého služebníka Davida nám dal mocného Zachránce,"],[70,"jak od dávných časů slíbil ústy svých svatých proroků:"],[71,"že nás zachrání před našimi nepřáteli a z rukou všech, kdo nás nenávidí."],[72,"Tak projevil milosrdenství našim otcům a připomněl svou svatou smlouvu,"],[73,"přísahu, kterou dal našemu otci Abrahamovi."],[74,"Slíbil, že nás vysvobodí z rukou nepřátel, abychom mu mohli beze strachu sloužit"],[75,"ve svatosti a spravedlnosti před ním po všechny své dny."],[76,"A ty, dítě, budeš nazýváno prorokem Nejvyššího, protože půjdeš před Pánem a budeš mu připravovat cestu."],[77,"Jeho lidu dáš poznat záchranu, která přichází odpuštěním jejich hříchů."],[78,"To všechno přichází z hlubokého milosrdenství našeho Boha. Díky němu nás navštíví světlo přicházející shůry,"],[79,"aby zazářilo těm, kdo žijí v temnotě a ve stínu smrti, a vedlo naše kroky na cestu pokoje.“"],[80,"Dítě rostlo a sílilo v duchu. Žilo v pustině až do dne, kdy veřejně vystoupilo před Izraelem."]]}];

LUKE_SECTIONS["2"] = [{"title":"Narození Ježíše","range":"Lk 2,1–20","thoughts":[],"verses":[[1,"V těch dnech vydal císař Augustus nařízení, aby bylo provedeno sčítání obyvatel celé říše."],[2,"Toto první sčítání se konalo v době, kdy Sýrii spravoval Quirinius."],[3,"Všichni se šli dát zapsat, každý do svého města."],[4,"Také Josef se vydal z galilejského Nazareta do Judska, do Davidova města zvaného Betlém, protože pocházel z Davidova rodu."],[5,"Šel se dát zapsat spolu s Marií, svou snoubenkou, která čekala dítě."],[6,"Když byli v Betlémě, přišel čas jejího porodu."],[7,"Porodila svého prvorozeného syna, zavinula ho do plenek a položila do jeslí, protože pro ně nebylo místo v ubytování."],[8,"V té krajině byli pastýři, kteří nocovali venku a hlídali svá stáda."],[9,"Najednou se před nimi objevil Pánův anděl a ozářila je Pánova sláva. Pastýři se velmi polekali."],[10,"Anděl jim řekl: „Nebojte se. Přináším vám dobrou zprávu o veliké radosti, která je určena všemu lidu."],[11,"Dnes se vám v Davidově městě narodil Zachránce, Mesiáš a Pán."],[12,"A toto vám bude znamením: Najdete dítě zavinuté do plenek a položené v jeslích.“"],[13,"Vtom se k andělovi přidalo veliké množství nebeských zástupů. Chválili Boha a říkali:"],[14,"„Sláva Bohu na výsostech a na zemi pokoj lidem, v nichž má zalíbení.“"],[15,"Když od nich andělé odešli do nebe, pastýři si řekli: „Pojďme do Betléma a podívejme se na to, co se stalo a co nám Pán oznámil.“"],[16,"Rychle se tam vydali a našli Marii, Josefa i dítě, které leželo v jeslích."],[17,"Když je uviděli, vyprávěli, co jim bylo o tom dítěti řečeno."],[18,"Všichni, kdo jejich vyprávění slyšeli, se tomu divili."],[19,"Marie si však všechna ta slova uchovávala a přemýšlela o nich ve svém srdci."],[20,"Pastýři se potom vrátili. Oslavovali a chválili Boha za všechno, co slyšeli a viděli, protože to bylo přesně tak, jak jim bylo řečeno."]]},{"title":"Ježíš je přinesen do chrámu","range":"Lk 2,21–40","thoughts":[],"verses":[[21,"Když uplynulo osm dní a dítě mělo být obřezáno, dostalo jméno Ježíš, jak ho nazval anděl ještě před jeho početím."],[22,"Když podle Mojžíšova zákona uplynula doba očišťování, přinesli Ježíše do Jeruzaléma, aby ho představili Pánu."],[23,"V Pánově zákoně je totiž napsáno: „Každý prvorozený syn bude zasvěcen Pánu.“"],[24,"Zároveň přinesli oběť, jak stanoví Pánův zákon: pár hrdliček nebo dvě holoubata."],[25,"V Jeruzalémě tehdy žil muž jménem Simeon. Byl spravedlivý a zbožný, očekával útěchu Izraele a byl s ním Duch svatý."],[26,"Duch svatý mu zjevil, že nezemře, dokud neuvidí Pánova Mesiáše."],[27,"Veden Duchem přišel Simeon do chrámu právě ve chvíli, kdy rodiče přinášeli malého Ježíše, aby s ním vykonali to, co předepisoval Zákon."],[28,"Simeon vzal dítě do náruče, chválil Boha a řekl:"],[29,"„Teď už, Pane, můžeš svého služebníka podle svého slova propustit v pokoji,"],[30,"protože mé oči viděly tvou záchranu,"],[31,"kterou jsi připravil před očima všech národů:"],[32,"světlo, které tě zjeví národům, a slávu tvého lidu Izraele.“"],[33,"Ježíšův otec a matka se divili tomu, co se o něm říkalo."],[34,"Simeon jim požehnal a Marii, jeho matce, řekl: „Toto dítě je určeno k pádu i povstání mnoha lidí v Izraeli a bude znamením, kterému budou odporovat."],[35,"I tvou vlastní duší pronikne meč. Tak vyjdou najevo myšlenky mnoha srdcí.“"],[36,"Byla tam také prorokyně Anna, dcera Fanuelova z kmene Ašer. Byla už velmi stará. Po svatbě žila se svým mužem sedm let"],[37,"a potom zůstala vdovou až do svých čtyřiaosmdesáti let. Téměř neopouštěla chrám a dnem i nocí sloužila Bohu postem a modlitbami."],[38,"Právě v tu chvíli přišla, vzdávala Bohu díky a mluvila o Ježíši všem, kdo očekávali vykoupení Jeruzaléma."],[39,"Když Josef s Marií splnili všechno, co ukládal Pánův zákon, vrátili se do Galileje, do svého města Nazareta."],[40,"Dítě rostlo a sílilo, bylo plné moudrosti a spočívala na něm Boží milost."]]},{"title":"Dvanáctiletý Ježíš v chrámu","range":"Lk 2,41–52","thoughts":[],"verses":[[41,"Ježíšovi rodiče chodili každý rok do Jeruzaléma na velikonoční svátky."],[42,"Když bylo Ježíšovi dvanáct let, vydali se tam jako obvykle na svátky."],[43,"Po skončení svátečních dnů se vraceli domů, ale chlapec Ježíš zůstal v Jeruzalémě. Jeho rodiče o tom nevěděli."],[44,"Mysleli si, že jde někde mezi ostatními poutníky, a tak urazili celý den cesty. Potom ho začali hledat mezi příbuznými a známými."],[45,"Když ho nenašli, vrátili se do Jeruzaléma a hledali ho tam."],[46,"Po třech dnech ho našli v chrámu. Seděl mezi učiteli, poslouchal je a kladl jim otázky."],[47,"Všichni, kdo ho slyšeli, žasli nad jeho porozuměním a odpověďmi."],[48,"Když ho rodiče uviděli, byli ohromeni. Jeho matka mu řekla: „Synu, proč jsi nám to udělal? Tvůj otec a já jsme tě s úzkostí hledali.“"],[49,"Ježíš jim odpověděl: „Proč jste mě hledali? Nevěděli jste, že musím být tam, kde jde o mého Otce?“"],[50,"Oni však nepochopili, co jim tím chtěl říct."],[51,"Potom se s nimi vrátil do Nazareta a poslouchal je. Jeho matka si všechna ta slova uchovávala v srdci."],[52,"Ježíš rostl v moudrosti i věku a získával stále větší přízeň u Boha i u lidí."]]}];

LUKE_SECTIONS["3"] = [{"title":"Jan Křtitel připravuje cestu","range":"Lk 3,1–20","thoughts":[],"verses":[[1,"V patnáctém roce vlády císaře Tiberia, když Pontius Pilát spravoval Judsko, Herodes vládl v Galileji, jeho bratr Filip v Itureji a Trachonitidě a Lysanias v Abiléně,"],[2,"v době velekněží Annáše a Kaifáše, promluvil Bůh na poušti k Janovi, synu Zachariášovu."],[3,"Jan procházel celým okolím Jordánu a hlásal křest obrácení na odpuštění hříchů."],[4,"Tak se naplňovalo to, co je napsáno v knize proroka Izajáše: „Hlas volajícího na poušti: Připravte cestu Pánu, narovnejte mu stezky."],[5,"Každé údolí bude vyplněno, každá hora a pahorek budou sníženy. Křivé cesty se narovnají a nerovné se vyhladí."],[6,"A všichni lidé uvidí Boží záchranu.“"],[7,"Zástupům, které přicházely, aby se od něj daly pokřtít, Jan říkal: „Hadí plemeno! Kdo vám namluvil, že uniknete přicházejícímu hněvu?"],[8,"Přinášejte ovoce, které odpovídá skutečnému obrácení. A nezačínejte si říkat: ‚Naším otcem je Abraham.‘ Říkám vám, že Bůh může Abrahamovi vzbudit děti i z těchto kamenů."],[9,"Sekera už leží u kořenů stromů. Každý strom, který nenese dobré ovoce, bude poražen a hozen do ohně.“"],[10,"Lidé se ho ptali: „Co tedy máme dělat?“"],[11,"Jan jim odpovídal: „Kdo má dva oděvy, ať se rozdělí s tím, kdo nemá žádný. A kdo má jídlo, ať udělá totéž.“"],[12,"Přišli se dát pokřtít i výběrčí daní a ptali se ho: „Mistře, co máme dělat my?“"],[13,"Řekl jim: „Nevybírejte víc, než kolik vám bylo stanoveno.“"],[14,"Ptali se ho také vojáci: „A co máme dělat my?“ Odpověděl jim: „Nikoho nevydírejte ani falešně neobviňujte a spokojte se se svým žoldem.“"],[15,"Lidé byli plní očekávání a všichni si v duchu říkali, jestli snad Jan není Mesiáš."],[16,"Jan proto všem odpověděl: „Já vás křtím vodou. Přichází však někdo mocnější než já. Nejsem hoden ani rozvázat řemínek jeho sandálů. On vás bude křtít Duchem svatým a ohněm."],[17,"V ruce má lopatu, aby důkladně vyčistil svůj mlat. Pšenici shromáždí do sýpky, ale plevy spálí neuhasitelným ohněm.“"],[18,"Takto i mnoha dalšími slovy Jan lidi povzbuzoval a hlásal jim dobrou zprávu."],[19,"Když však napomínal vládce Heroda kvůli Herodiadě, ženě jeho bratra, a také kvůli všemu zlému, co Herodes dělal,"],[20,"Herodes ke všemu ostatnímu přidal ještě to, že nechal Jana zavřít do vězení."]]},{"title":"Ježíšův křest","range":"Lk 3,21–22","thoughts":[],"verses":[[21,"Když se dával křtít všechen lid, byl pokřtěn také Ježíš. Když se potom modlil, otevřelo se nebe"],[22,"a Duch svatý na něj sestoupil v tělesné podobě jako holubice. Z nebe zazněl hlas: „Ty jsi můj milovaný Syn, v tobě mám zalíbení.“"]]},{"title":"Ježíšův rodokmen","range":"Lk 3,23–38","thoughts":[],"verses":[[23,"Když Ježíš začínal své působení, bylo mu asi třicet let. Lidé ho pokládali za syna Josefa, syna Heliho,"],[24,"syna Matata, syna Léviho, syna Melchiho, syna Jannaje, syna Josefa,"],[25,"syna Matatiáše, syna Amose, syna Nahuma, syna Esliho, syna Naggaje,"],[26,"syna Maata, syna Matatiáše, syna Semeina, syna Josecha, syna Jody,"],[27,"syna Joanana, syna Resy, syna Zerubábela, syna Šealtiela, syna Neriho,"],[28,"syna Melchiho, syna Addiho, syna Kosama, syna Elmadama, syna Era,"],[29,"syna Jozua, syna Eliezera, syna Jorima, syna Matata, syna Léviho,"],[30,"syna Simeona, syna Judy, syna Josefa, syna Jonama, syna Eliakima,"],[31,"syna Meley, syna Menny, syna Mattaty, syna Nátana, syna Davida,"],[32,"syna Jišaje, syna Obéda, syna Bóaze, syna Salmona, syna Nachšona,"],[33,"syna Amínadaba, syna Admina, syna Arniho, syna Chesrona, syna Perese, syna Judy,"],[34,"syna Jákoba, syna Izáka, syna Abrahama, syna Teracha, syna Nachora,"],[35,"syna Serúga, syna Reúa, syna Pelega, syna Ébera, syna Šelacha,"],[36,"syna Kenana, syna Arpakšáda, syna Šéma, syna Noema, syna Lámecha,"],[37,"syna Metuzaléma, syna Henocha, syna Jereda, syna Mahalalela, syna Kenana,"],[38,"syna Enóše, syna Šéta, syna Adama, syna Božího."]]}];

LUKE_SECTIONS["4"] = [{"title":"Ježíšovo pokušení","range":"Lk 4,1–13","thoughts":[],"verses":[[1,"Ježíš, pak, pln když byl Ducha svatého, vrátil se od Jordánu, a puzen je v Duchu na poušť."],[2,"za čtyřidceti dní pokoušín byl od ďábla, a nic nejedl v těch dnech. Ale když se skonali, potom zlačněl."],[3,"řekl mu ďábel: Jestliže jsi Syn Boží, rci kamenu tomuto, ať je chléb."],[4,"odpověděl mu Ježíš, řka: Psánoť je: Že ne samým chlebem živ bude člověk, ale každým slovem Božím."],[5,"vedl ho ďábel na horu vysokou, a ukázal mu všechna království okršlku země pojednou."],[6,"řekl mu ďábel: Toběť dám tuto všecku moc i slávu; nebo mně dána je, a komuž bych koli chtěl, dám ji."],[7,"Protož ty pokloníš-li se přede mnou, budeť všechno tvé."],[8,"odpověděv Ježíš, řekl mu: Jdi pryč ode mne, satanáši; nebo psáno je:Pánu Bohu svému budeš se klaněti, a mu samému sloužiti."],[9,"vedl ho do Jeruzaléma, a postavil ho na vrchu chrámu, a řekl mu: Jsi-li Syn Boží, pusť se odtud dolů."],[10,"Protože psáno je: Že andělům svým přikáže o tobě, aby tě ostříhali,"],[11,"že tě na ruce uchopí, abys neurazil o kámen nohy své."],[12,"odpovídaje, dí mu Ježíš: Pověřeklnoť je: Nebudeš pokoušeti Pána Boha svého."],[13,"dokonav všechna pokušení ďábel, odšel od něj až do času."]]},{"title":"Ježíš začíná působit v Galileji","range":"Lk 4,14–15","thoughts":[],"verses":[[14,"navrátil se Ježíš v moci Ducha do Galilee, a vyšla pověst o něm po vší té okolní krajině."],[15,"on učil v školách jejich, a slaven byl ode všech."]]},{"title":"Ježíš v Nazaretě","range":"Lk 4,16–30","thoughts":[],"verses":[[16,"přišel do Nazaréta, kdež byl vychován, a všel podlé obyčeje svého v den sobotní do školy. A vstal, aby četl."],[17,"dána mu kniha Izaiáše proroka. A otevřev knihu, nalezl místo, kdež bylo napsáno:"],[18,"Duch Páně nade mnou, proto že pomazal mne, kázati evangelium chudým poslal mne, a uzdravovati skroušené srdcem, zvěstovati jatým propuštění a slepým vidění, a propustiti ssoužené v svobodu,"],[19,"zvěstovati léto Páně vzácné."],[20,"zavřev knihu, a vrátiv služebníku, posadil se. A všech v škole oči byly obráceny naň."],[21,"počal mluviti k nim: Že dnes naplnilo se písmo toto v uších vašich."],[22,"všichni mu posvědčovali, a divili se libým slovům, pocházejícím z úst jeho, a říkali: Zdaliž tento není syn Jozefův?"],[23,"dí k nim: Zajisté řeklte mi toto podobenství: Lékaři, uzdrav se sám. Které věci slyšeli jsme, žes činil v Kafarnaum, učiň i zde v své vlasti."],[24,"řekl jim: Amen, říkám vám, žeť žádný prorok není vzácen v vlasti své."],[25,"Ale v pravdě říkám vám, že mnoho vdov bylo za dnů Eliáše v lidu Izraelském, když zavříno bylo nebe za tři léta a za šest měsíců, a když byl hlad veliký po vší zemi,"],[26,"Však Eliáš k žádné z nich není poslán, než toliko do Sarepty Sidonské k ženě vdově."],[27,"mnoho malomocných bylo v lidu Izraelském za Elizea proroka, a však žádný z nich není očištěn, než Náman Syrský."],[28,"naplněni byli všichni v škole hněvem, slyšíce to."],[29,"vstalše, vyvedli ho ven z města, a vedli ho až na vrch hory, na níž město jejich bylo vzděláno, aby ho dolů sstrčili."],[30,"Ale on bera se prostředkem jich, ušel."]]},{"title":"Uzdravení v Kafarnaum","range":"Lk 4,31–44","thoughts":[],"verses":[[31,"sstoupil do Kafarnaum, města Galilejského, a učil je ve dny sobotní."],[32,"divili se velmi učení jeho, nebo mocná byla řeč jeho."],[33,"Byl pak v škole člověk, mělaí ducha ďábelství nečistého. A zvolal hlasem velikým,"],[34,"Řka: Ach, což je tobě do nás, Ježíši Nazaretský? Přišel jsi zatraťiti nás? Znám tě, kdo jsi, že ten Svatý Boží."],[35,"přimluvil mu Ježíš, řka: Umlkniž a vyjdi od něj. A povrha ho ďábel mezi ně, vyšel od něj, a nic mu neuškodil."],[36,"přišel strach na všecky, a rozmlouvali vespolek, řkouce: Jaké je toto slovo, že v moci a síle přikazuje nečistým duchům, a vycházejí?"],[37,"rozcházela se o něm pověst po všelikém místě té okolní krajiny."],[38,"Vstav pak ze školy, všel do domu Šimonova. Svegruše pak Šimonova trápena byla těžkou zimnicí. A prosili ho za ni."],[39,"stoje nad ní, přimluvil zimnici, i přestala jí. A ona hned vstalši, posluhovala jim."],[40,"Při západu pak slunce všichni, kteříž měli nemocné rozličnými neduhy, vodili je k němu, a on na jednoho každého z nich ruce vzkládav, uzdravoval je."],[41,"Od mnohých také ďábelství vycházela, křičící a říkající: Ty jsi Kristus, Syn Boží. Ale přimlouvaje, nedopouštěl jim mluviti; nebo věděli, že je on Kristus."],[42,"jakž byl den, vyšel, bral se na pusté místo. A hledali ho zástupové, a přišli až k němu, a zdržovali ho, aby neodcházel od nich."],[43,"On pak řekl jim: A jinýmť městům musím zvěstovati království Boží; nebo na to poslán jsem."],[44,"kázal v školách Galilejských."]]}];

LUKE_SECTIONS["5"] = [{"title":"Povolání prvních učedníků","range":"Lk 5,1–11","thoughts":[],"verses":[[1,"Stalo se pak, když se zástup na něj valil, aby slyšeli slovo Boží, že on stál podlé jezera Genezaretského."],[2,"uviděl dvě lodí, any stojí u jezera, rybáři pak sstoupivše z nich, vypírali sítí."],[3,"vstoupiv na jednu z těch lodí, kteráž byla Šimonova, prosil ho, aby od země odvezl maličko. A posadiv se, učil z lodí zástupy."],[4,"když přestal mluviti, dí k Šimonovi: Vez na hlubinu, a rozestřete síti své k lovení."],[5,"odpověděv Šimon, řekl mu: Mistře, přes celou noc pracovavše, nic jsme nepopadli, ale k slovu tvému rozestru sít."],[6,"když to učinili, zahrnuli množství veliké ryb, tak že se trhala sít jejich."],[7,"ponukli tovaryšů, kteříž byli na druhé lodí, aby přišli a pomohli jim. A přišli a naplnili obě lodí, tak že se pohřižovaly."],[8,"To když uviděl Šimon Petr, padl k nohám Ježíšovým, řka: Odejdi ode mne, Pane, neboť jsem člověk hříšný."],[9,"Hrůza zajisté byla ho obklíčila, i všecky, kteříž s ním byli, nad tím lovením ryb, kteréž byli popadli,"],[10,"též Jakuba a Jana, syny Zebedeovy, kteříž byli tovaryši Šimonovi. A dí Šimonovi Ježíš: Nebojž se. Již od tohoto času lidi budeš loviti."],[11,"přivezše k břehu lodí, a všechno opustivše, šli za ním."]]},{"title":"Očištění malomocného","range":"Lk 5,12–16","thoughts":[],"verses":[[12,"stalo se, když byl v jednom městě, a aj, muž plný malomocenství. A když uviděl Ježíše, padl na tvář, a prosil ho, řka: Pane, kdybys chtěl, můžeš mne očistiti."],[13,"vztáhl ruku, dotekl se ho, řka: Chci, buď čist. A hned odešlo od něj malomocenství."],[14,"přikázal mu, aby žádnému nepravil, ale jdi, ukaž se knězi, a obětuj za očištění své, jakož přikázal Mojžíš, na svědectví jim."],[15,"rozhlašovala se více řeč o něm, a scházeli se zástupové mnozí, aby ho slyšeli, a uzdravováni byli od něj v svých nemocech."],[16,"On pak odcházel na pouště, a modlil se."]]},{"title":"Uzdravení ochrnutého","range":"Lk 5,17–26","thoughts":[],"verses":[[17,"stalo se v jeden den, že on učil. A seděli také tu i farizeové a zákona učitelé, kteříž se byli sešli ze všech městeček Galilejských a Judských i z Jeruzaléma, a moc Páně přítomna byla k uzdravování jich."],[18,"aj, muži nesli na loži člověka, kterýž byl šlakem poražený, i hledali vnésti ho a položiti před něj."],[19,"nenalezše, kterou by ho stranou vnesli pro zástup, vstoupili na dům, a skrze podlahu spustili ho s ložem u prostřed před Ježíše."],[20,"Kterýžto když viděl víru jejich, řekl mu: Člověče, odpuštěniť jsou tobě hříchové tvoji."],[21,"počali přemyšlovati zákonníci a farizeové, řkouce: Kdo je tento, kterýž mluví rouhání? Kdo může odpustiti hříchy, jediné sám Bůh?"],[22,"Poznav pak Ježíš myšlení jejich, odpovídaje, řekl jim: Co přemyšlujete v srdcích svých?"],[23,"Co je snáze říci: Odpouštějí se tobě hříchové tvoji, čili říci: Vstaň a choď?"],[24,"Ale abyste věděli, že Syn člověka má moc na zemi odpouštěti hříchy, řekl šlakem poraženému: Toběť říkám: Vstaň, a vezma lůžko své, jdi do domu svého."],[25,"hned vstal před nimi, vzal, na čemž ležel, i odšel do domu svého, velebě Boha."],[26,"užasli se všichni, a velebili Boha, a naplněni jsou bázní, řkouce: Viděli jsme dnes divné věci."]]},{"title":"Povolání Léviho","range":"Lk 5,27–32","thoughts":[],"verses":[[27,"potom vyšel a uviděl celného, jménem Léví, sedícího na cle. A řekl mu: Poď za mnou."],[28,"opustiv všechno, vstal, šel za ním."],[29,"udělal mu hody veliké Léví v domě svém, a byl zástup veliký celníků i jiných, kteříž s ním stolili."],[30,"reptali zákonníci a farizeové, řkouce učedníkům jeho: Proč s celníky a hříšníky jíte a pijete?"],[31,"odpověděv Ježíš, řekl jim: Nepotřebujíť zdraví lékaře, ale nemocní."],[32,"Nepřišelť jsem volati spravedlivých, ale hříšných ku pokání."]]},{"title":"Otázka půstu","range":"Lk 5,33–39","thoughts":[],"verses":[[33,"oni řekli mu: Proč učedlníci Janovi postí se často a modlí se, podobně i farizejští, tvoji pak jedí a pijí?"],[34,"On pak řekl jim: Zdali můžete synům ženicha, dokudž s nimi je ženich, kázati se postiti?"],[35,"Přijdouť pak dnové, když odjat bude od nich ženich, tehdážť se budou postiti v těch dnech."],[36,"Pravil pak jim i podobenství. Že žádný záplaty oděvy nového nepřišívá k rouchu vetchému; sic jinak to nové roztrhuje, a vetchému nepřipadá záplata z nového."],[37,"žádný nevlévá vína nového do nádob starých; sic jinak víno nové rozpučí nádoby, a samo vyteče, a nádoby se pokazí."],[38,"Ale víno nové v nádoby nové má lito býti, a obé bude zachováno."],[39,"aniž kdo, když pije staré, hned chce nového, ale díť: Staré lepší je."]]}];
LUKE_SECTIONS["6"] = [{"title":"Ježíš a sobota","range":"Lk 6,1–11","thoughts":[],"verses":[[1,"stalo se v druhou sobotu, že šel Ježíš skrze obilí. A trhali učedlníci jeho klasy, a rukama vymínajíce, jedli."],[2,"Tehdy někteří z farizeů řekli jim: Proč činíte, čehož nesluší činiti v sobotu?"],[3,"odpověděv Ježíš, řekl jim: Což jste ani toho nečtli, co udělal David, když lačněl, on i ti, kteříž s ním byli?"],[4,"Kterak všel do domu Božího, a chleby posvátné vzal a jedl, a dal i těm, kteříž s ním byli, jichž nenáleží jísti než toliko samým kněžím?"],[5,"řekl jim: Že je Syn člověka pánem také i dne sobotního."],[6,"Stalo se pak i v jinou sobotu, že všel do školy Ježíš a učil. A byl tu člověk, jehož pravá ruka byla uschlá."],[7,"šetřili ho zákonníci a farizeové, bude-li v sobotu uzdravovati, aby nalezli, z čeho by ho obžalovali."],[8,"Ale on znal přemyšlování jejich. A dí člověku, kterýž měl ruku uschlou: Vstaň, a stůj v prostředku. A on vstal, stál."],[9,"řekl jim Ježíš: Otíži se vás na jednu věc: Sluší-li v sobotu dobře činiti, čili zle, duši zachovati, čili zatratiti?"],[10,"pohleděv na ně na všecky kolem, dí člověku tomu: Vztáhni tu ruku svou. A on udělal tak. A přivedena je k zdraví ruka jeho jako druhá."],[11,"Oni pak naplněni jsou hněvivou nemoudrostí, a rozmlouvali mezi sebou, co by udělat měli Ježíšovi."]]},{"title":"Vyvolení Dvanácti","range":"Lk 6,12–16","thoughts":[],"verses":[[12,"stalo se v těch dnech, vyšel na horu k modlení. A byl tam přes noc na modlitbě Boží."],[13,"když byl den, povolal učedníků svých, a vyvolil z nich dvanácte, kteréž i apoštoly nazval:"],[14,"(Šimona, kterémuž také dal jméno Petr, a Ondřeje bratra jeho, Jakuba a Jana, Filipa a Bartoloměje,"],[15,"Matouše a Tomáše, Jakuba Alfeova, a Šimona, kterýž slove Zelótes,"],[16,"Judu Jakubova, a Jidáše Aškariotského, kterýž potom byl zrádce.)"]]},{"title":"Ježíš učí a uzdravuje","range":"Lk 6,17–19","thoughts":[],"verses":[[17,"sstoupiv s nimi, stál na místě polním, a zástup učedníků jeho, a množství veliké lidu ze všeho Judstva i z Jeruzaléma, i z Týru i z Sidonu, kteříž při moři jsou, kteříž byli přišli, aby ho slyšeli, a uzdraveni byli od neduhů svých,"],[18,"kteříž trápeni byli od duchů nečistých. A byli uzdravováni."],[19,"celý zástup hledal se ho dotknouti; nebo moc z něj vycházela, a uzdravovala všecky."]]},{"title":"Blahoslavenství a běda","range":"Lk 6,20–26","thoughts":[],"verses":[[20,"on pozdvih očí svých na učedníky, řekl: Blahoslavení chudí, nebo vaše je království Boží."],[21,"Blahoslavení, kteříž nyní lačníte, nebo nasyceni budete. Blahoslavení, kteříž nyní plačete, nebo smáti se budete."],[22,"Blahoslavení budete, když vás nenáviděti budou lidé, a když vás vyobcují, a haněti budou, a vyvrhou jméno vaše jako zlé, pro Syna člověka."],[23,"Radujte se v ten den, a veselte se, nebo aj, odplata vaše mnohá v nebesích. Takť zajisté činívali prorokům otcové jejich."],[24,"Ale běda vám bohatým, nebo vy již máte potěšení své."],[25,"Běda vám, kteříž jste nasyceni, nebo lačněti budete. Běda vám, kteříž se nyní smějete, nebo kvíliti a plakati budete."],[26,"Běda vám, když by dobře o vás mluvili všichni lidé; nebo tak činívali falešným prorokům otcové jejich."]]},{"title":"Láska k nepřátelům","range":"Lk 6,27–36","thoughts":[],"verses":[[27,"Ale vámť říkám, kteříž slyšíte: Milujte nepřátely své, dobře čiňte těm, kteříž vás nenávidí,"],[28,"Dobrořečte těm, kteříž vás proklínají, a modlte se za ty, kteříž vám bezpráví činí."],[29,"udeřil-li by tebe kdo v líce, nasaď mu i druhého, a tomu, kterýž tobě odjímá plášť, také i sukně nebraň."],[30,"Každému pak prosícímu tebe dej, a od toho, kterýž béře tvé věci, zase nežádej."],[31,"jakž chcete, aby vám lidé činili, i vy jim též podobně čiňte."],[32,"Protože jestliže milujete ty, kteříž vás milují, jakou míti budete milost? Protože i hříšníci milují ty, od nichž milováni bývají."],[33,"budete-li dobře činiti těm, kteříž vám dobře činí, jakou máte milost? Však i hříšnící totéž činí."],[34,"budete-li půjčovati těm, od kterýchž se nadějete zase vzíti, jakou máte milost? Však i hříšníci hříšníkům půjčují, aby tolikéž zase vzali."],[35,"Nýbrž milujte nepřátely své, a dobře čiňte, a půjčujte, nic se odtud nenadějíce, a budeť odplata vaše mnohá, a budete synové Nejvyššího. Protože on dobrotivý je i k nevděčným a zlým."],[36,"Protož buďte milosrdní, jako i Otec váš milosrdný je."]]},{"title":"Nesuďte","range":"Lk 6,37–42","thoughts":[],"verses":[[37,"Nesuďte, a nebudete souzeni. Nepotupujte, a nebudete potupeni. Odpouštějte, a budeť vám odpuštěno."],[38,"Dávejte, a budeť vám dáno. Míru dobrou, natlačenou, a natřesenou, a osutou dadíť v lůno vaše; touž zajisté měrou, kterouž měříte, bude vám zase odměřeno."],[39,"Pověděl jim také i podobenství: Zdali může slepý slepého vésti? Zdaž oba do jámy neupadnou?"],[40,"Neníť učedník nad mistra svého, ale dokonalý bude každý, bude-li jako mistr jeho."],[41,"Což pak vidíš mrvu v oku bratra svého, a břevna, kteréž je v tvém vlastním oku, neznamenáš?"],[42,"Aneb jak můžeš říci bratru svému: Bratře, nechať vyňmu mrvu, kteráž je v oku tvém, sám v oku svém břevna nevida? Pokrytče, vyvrz prvé břevno z oka svého, a tehdy prohlédneš, abys vyňal mrvu, kteráž je v oku bratra tvého."]]},{"title":"Strom a jeho ovoce","range":"Lk 6,43–45","thoughts":[],"verses":[[43,"Protožeť není ten strom dobrý, kterýž nese ovoce zlé, aniž je strom zlý, kterýž nese ovoce dobré."],[44,"Každý zajisté strom po svém vlastním ovoci bývá poznán; nebo nezbírají s trní fíků, ani s hloží zbírají hroznů."],[45,"Dobrý člověk z dobrého pokladu srdce svého vynáší dobré, a zlý člověk ze zlého pokladu srdce svého vynáší zlé. Protože z hojnosti srdce mluví ústa jeho."]]},{"title":"Dům na skále","range":"Lk 6,46–49","thoughts":[],"verses":[[46,"Co pak mi říkáte: Pane, Pane, a neděláte, což říkám?"],[47,"Každý kdož přichází ke mně, a slyší slovo mé, a zachovává je, ukáži vám, komu by podoben byl."],[48,"Podoben je člověku stavějícímu dům, kterýž kopal a vytesal hluboko, a založil grunty v skále. A když se povodeň strhla, obořila se řeka na dům ten, ale nemohla ním pohnouti, nebo byl založen na skále."],[49,"Ale kdož slyší a nečiní, podoben je člověku, kterýž staví dům svůj na zemi bez gruntu. Na kterýž obořila se řeka, a on hned padl, i byl pád domu toho veliký."]]}];

LUKE_SECTIONS["7"] = [{"title":"Víra setníka","range":"Lk 7,1–10","thoughts":[],"verses":[[1,"když vykonal všechna slova svá při přitomnosti lidu, všel do Kafarnaum."],[2,"Setníka pak nějakého služebník nemocen když byl, k smrti se přibližoval, kteréhož on sobě mnoho vážil."],[3,"uslyšav o Ježíšovi, poslal k němu starší Židovské, prose ho, aby přišel a uzdravil služebníka jeho."],[4,"oni přišelše k Ježíšovi, prosili ho snažně, řkouce: Hoden je, abys mu to udělal."],[5,"Protože miluje národ náš, a školu on nám vystavěl."],[6,"Ježíš šel s nimi. A když již nedaleko byl od domu, poslal k němu ten setník přátely, řka mu: Pane, nepřidávej sobě práce. (Nejsem zajisté hoden, abys všel pod střechu mou."],[7,"protož jsem i sebe samého za nehodného položil, abych přišel k tobě.) Ale rci slovem, a budeť uzdraven služebník můj."],[8,"Protože i já jsem člověk pod mocí postavený, měl pod sebou žoldnéře, a řeklm tomuto: Jdi, a jde, a jinému: Přiď, a přijde, a služebníku svému: Učiň toto, a učiní."],[9,"uslyšav to Ježíš, podivil se mu, a obrátiv se, řekl zástupu, kterýž za ním šel: Pravím vám, že ani v Izraeli nenalezl jsem tak veliké víry."],[10,"Vrátivše se pak domů ti, kteříž posláni byli, nalezli služebníka, kterýž nemocen byl, zdravého."]]},{"title":"Vzkříšení syna vdovy v Naim","range":"Lk 7,11–17","thoughts":[],"verses":[[11,"stalo se potom, šel do města, kteréž slove Naim, a šli s ním učedlníci jeho mnozí a zástup veliký."],[12,"když se přiblížil k bráně města, aj, mrtvý byl nesen ven, syn jediný matky své, a ta vdova byla, a zástup města mnohý s ní."],[13,"Kteroužto když uviděl Pán, milosrdenstvím hnut je k ní, a řekl jí: Neplačiž."],[14,"přistoupiv, dotekl se már. (Ti pak,kteříž nesli, zastavili se.) A řekl: Mládenče,toběť říkám, vstaň."],[15,"posadil se ten mrtvý, a počal mluviti. A dal ho mateři jeho."],[16,"podjala všecky bázeň, i velebili Boha, řkouce: Prorok veliký povstal mezi námi, a Bůh navštívil lid svůj."],[17,"vyšla řeč ta o něm po všem Judstvu i po vší okolní krajině."]]},{"title":"Jan Křtitel a Ježíš","range":"Lk 7,18–35","thoughts":[],"verses":[[18,"zvěstovali Janovi učedlníci jeho o všech těchto věcech. A zavolav kterýchs dvou z učedníků svých Jan,"],[19,"Poslal k Ježíšovi, řka: Ty-li jsi ten, kterýž přijíti má, čili jiného čekati máme?"],[20,"Přišelše pak k němu muži ti, řekli: Jan Křtitel poslal nás k tobě řka: Ty-li jsi ten, kterýž přijíti má, čili jiného čekati máme?"],[21,"v touž hodinu mnohé uzdravil od neduhů, od nemocí a duchů zlých, a slepým mnohým zrak dal."],[22,"Odpověděv pak Ježíš, řekl jim: Jdouce, povězte Janovi, co jste viděli a slyšeli, že slepí vidí, kulhaví chodí, malomocní očištění přijímají, hluší slyší, mrtví z mrtvých vstávají, chudým se zvěstuje evangelium."],[23,"blahoslavený je, kdož by se na mně nezhoršil."],[24,"když odešli poslové Janovi, počal praviti zástupům o Janovi: Co jste vyšli na poušť spatřovati? Třtinu-li, kteráž se větrem klátí?"],[25,"Aneb nač jste hleděti vyšli? Na člověka-li měkkým rouchem oděného? Hle, kteříž v rouše slavném a v rozkoši jsou, v domích královských jsou."],[26,"Aneb co jste vyšli viděti? Proroka-li? Jistě říkám vám, i více nežli proroka."],[27,"Tentoť je, o kterémž je psáno: Hle, já posílám anděla svého před tváří tvou, kterýž připraví cestu tvou před tebou."],[28,"Protože říkám vám, většího proroka mezi syny ženskými nad Jana Křtitele není žádného, ale kdož je menší v království Božím, většíť je nežli on."],[29,"celý lid slyše to i celníki, velebili Boha, když bylše pokřtěni křtem Janovým."],[30,"Ale farizeové a zákonníci pohrdli radou Boží sami proti sobě, nebyvše pokřtěni od něj."],[31,"řekl Pán: Komu tedy přirovnám lidi pokolení tohoto, a čemu podobni jsou?"],[32,"Podobni jsou dětem, kteříž na rynku sedí, a jedni na druhé volají, říkajíce: Pískali jsme vám, a neskákali jste; žalostně jsme naříkali vám, a neplakali jste."],[33,"Protože přišel Jan Křtitel, ani chleba nejeda, ani nepije vína, a říkáte: Ďábelství má."],[34,"Přišel Syn člověka, jeda a pije, a říkáte: Hle, člověk žráč a piján vína, přítel celníků a hříšníků."],[35,"Ale ospravedlněna je moudrost ode všech synů svých."]]},{"title":"Ježíš a hříšná žena","range":"Lk 7,36–50","thoughts":[],"verses":[[36,"Prosil ho pak jeden z farizeů, aby jedl s ním. Pročež všel do domu toho farizea, posadil se za stůl."],[37,"aj, žena v městě, kteráž byla hříšnice, zvěděvši, že by seděl za stolem v domě farizea, přinesla nádobu alabastrovou masti."],[38,"stojeci z zadu u noh jeho s pláčem, počala slzami smáčeti nohy jeho, a vlasy hlavy své vytírala, a líbala nohy jeho, a mastí mazala."],[39,"Uzřev pak to farizeus, kterýž ho byl pozval, řekl sám v sobě tak: Byť tento byl prorok, vědělť by, která a jaká je to žena, kteráž se ho dotýká; nebo hříšnice je."],[40,"odpověděv Ježíš, dí mu: Šimone, mámť něco pověřeklti. A on řekl: Mistře, pověz."],[41,"Dva dlužníky měl nějaký věřitel. Jeden dlužen byl pět set peněz, a druhý padesát."],[42,"když neměli, odkud by zaplatili, odpustil oběma. Pověziž tedy, který z nich více bude ho milovati?"],[43,"odpověděv Šimon, řekl: Mám za to, že ten, kterémuž více odpustil. A on řekl mu: Právě jsi rozsoudil."],[44,"obrátiv se k ženě, řekl Šimonovi: Vidíš tuto ženu? Všel jsem do domu tvého, vody nohám mým nedal jsi, ale tato slzami smáčela nohy mé, a vlasy hlavy své vytřela."],[45,"Nepolíbil jsi mne, ale tato, jakž jsem všel, nepřestala líbati noh mých."],[46,"Olejem hlavy mé nepomazal jsi, ale tato mastí mazala nohy mé."],[47,"Protož říkám tobě: Odpuštěniť jsou jí hříchové mnozí, neboť milovala mnoho. Komuť se pak málo odpouští, málo miluje."],[48,"řekl jí: Odpuštěniť jsou tobě hříchové."],[49,"počali, kteříž tu spolu seděli za stolem, říci sami mezi sebou: Kdo je tento, kterýž i hříchy odpouští?"],[50,"řekl ženě: Víra tvá tebe k spasení přivedla. Jdiž u pokoji."]]}];

LUKE_SECTIONS["8"] = [{"title":"Ženy, které doprovázely Ježíše","range":"Lk 8,1–3","thoughts":[],"verses":[[1,"stalo se potom, že on chodil po městech a po městečkách, káže a zvěstuje království Boží, a dvanácte s ním."],[2,"ženy některé, kteréž byl uzdravil od duchů zlých a od nemocí: Maria, kteráž slove Magdaléna, z níž bylo sedm ďáblů vyšlo,"],[3,"Johanna manželka Chuzova, úředníka Heródesova, a Zuzanna, a jiné mnohé, kteréž posluhovaly mu z statků svých."]]},{"title":"Podobenství o rozsévači","range":"Lk 8,4–15","thoughts":[],"verses":[[4,"Když se pak scházel zástup mnohý, a z měst hrnuli se k němu, mluvil v podobenství:"],[5,"Vyšel rozsevač, aby rozsíval símě své. A když on rozsíval, jedno padlo podlé cesty, i pošlapáno je, a ptáci nebeští zzobali je."],[6,"jiné padlo na skálu, a vzešlé uvadlo, proto že nemělo vláhy."],[7,"Jiné pak padlo mezi trní, a spolu zrostlé trní udusilo je."],[8,"jiné padlo v zemi dobrou, a když vzešlo, učinilo užitek stý. To pověděv, volal: Kdo má uši k slyšení, slyš."],[9,"otázali se ho učedlníci jeho, řkouce: Jaké je to podobenství?"],[10,"on řekl: Vám dáno je znáti tajemství království Božího, ale jiným v podobenství, aby hledíce, neviděli, a slyšíce, nerozuměli."],[11,"Jestiť pak podobenství toto: Símě je slovo Boží."],[12,"kteréž padlo podlé cesty, jsou ti, kteříž slyší, a potom přichází ďábel, a vynímá slovo z srdce jejich, aby nevěříce, spaseni nebyli."],[13,"Ale kteříž na skálu, ti když slyší, s radostí přijímají slovo, ale ti kořenů nemají; ti na čas věří, a v čas pokušení odstupují."],[14,"Kteréž pak mezi trní padlo, tiť jsou,kteříž slyší, ale po pečování a zboží a rozkošech života když šli, bývají udušeni, a nepřinášejí užitku."],[15,"Ale kteréž v zemi dobrou, ti jsou, kteříž v srdci ctném a dobrém, slyšíce slovo, zachovávají, a užitek přinášejí v trpělivosti."]]},{"title":"Lampa a světlo","range":"Lk 8,16–18","thoughts":[],"verses":[[16,"Žádný pak rozsvítě svíci, nepřikrývá jí nádobou, ani staví pod postel, ale na svícen staví, aby ti, kteříž vcházejí, světlo viděli."],[17,"Protože nic není tajného, což by nemělo býti zjeveno, ani co ukrytého, což by nemělo poznáno býti, a na světlo vyjíti."],[18,"Protož vizte, jak slyšíte. Protože kdož má, tomu bude dáno, a kdo nemá, i to, což domnívá se míti, bude odjato od něj."]]},{"title":"Ježíšova matka a bratři","range":"Lk 8,19–21","thoughts":[],"verses":[[19,"přišli k němu matka a bratří jeho, ale nemohli ho dojíti pro zástup."],[20,"pověděli mu, řkouce: Matka tvá a bratří tvoji stojí vně, chtíce tebe viděti."],[21,"on odpověděv, řekl jim: Matka má a bratří moji jsou ti, kteříž slovo Boží slyší a plní je."]]},{"title":"Utišení bouře","range":"Lk 8,22–25","thoughts":[],"verses":[[22,"Stalo se pak v jeden den, že on vstoupil na lodí i učedlníci jeho. A řekl jim: Přeplavme se přes jezero. A pustili se."],[23,"když se plavili, usnul. Potom přišel vítr bouřlivý na jezero, a lodí se naplňovala, tak že v nebezpečenství byli."],[24,"přistoupivše, zbudili ho, řkouce: Mistře, Mistře, hyneme. A on procítiv, přimluvil větru a zdutí vod. A spokojili se, a stalo se utišení."],[25,"řekl jim: Kdež je víra vaše? Kteřížto bojíce se, podivili se, vespolek řkouce: A kdo je tento, že i větrům přikazuje i vodám, a poslouchají ho?"]]},{"title":"Uzdravení posedlého","range":"Lk 8,26–39","thoughts":[],"verses":[[26,"přeplavili se do krajiny Gadarenské, kteráž je proti Galilei."],[27,"když vystoupil na zemi, potkal ho muž nějaký z města, kterýž měl ďábelství od mnoha časů, a rouchem se neodíval, ani v domě nebýval, ale v hrobích."],[28,"Uzřev pak Ježíše a zkřikna, padl před ním, a hlasem velikým řekl: Co je tobě do mne, Ježíši, Synu Boha nejvyššího? Prosím tebe, netrap mne."],[29,"Protože přikazoval tomu duchu nečistému, aby vyšel z toho člověka. Po mnohé zajisté časy jím lomcoval, tak že býval ukován řetězy, a v poutech ostříhán, ale on poláměl okovy, býval od ďábelství puzen na poušť."],[30,"otázal se ho Ježíš, řka: Jakť říkají? A on řekl: Množství. Protože bylo mnoho ďáblů vešlo do něj."],[31,"prosili ho, aby jim nepřikazoval odtud odjíti do propasti."],[32,"Bylo pak tu veliké stádo vepřů, kteříž se pásli na hoře. A prosili ho, aby jim dopustil do nich vjíti. A dopustil jim."],[33,"vyšelše ďáblové z toho člověka, vešli do vepřů, i hnalo se to stádo prudce s vrchu do jezera, a ztonulo."],[34,"když vidělše pastýři, co se stalo, utekli, a šedše, vypravovali to v městě i po vsech."],[35,"vyšli, aby viděli, co se stalo. A přišli k Ježíšovi, a nalezli člověka toho, z kteréhož ďáblové vyšli, oděného a mělaího rozum, an sedí u noh Ježíšových. A báli se."],[36,"vypravovali jim také ti, kteříž byli viděli, jak je ten vyproštěn, kterýž ďábelství měl."],[37,"prosilo ho všechno množství té okolní krajiny Gadarenských, aby odšel od nich; nebo bázní velikou naplněni byli. A on vstoupiv na lodí, navrátil se."],[38,"Prosil ho pak muž ten, z kteréhož ďáblové vyšli, aby s ním byl. Ale Ježíš propustil ho, řka:"],[39,"Navrať se do domu svého, a vypravuj, jak veliké věci udělal tobě Bůh. A odšel, po všem městě vypravuje, jak veliké věci udělal mu Ježíš."]]},{"title":"Jairova dcera a nemocná žena","range":"Lk 8,40–56","thoughts":[],"verses":[[40,"Stalo se pak, když se navrátil Ježíš, že přijal ho zástup; nebo všichni očekávali ho."],[41,"aj, přišel muž, kterémuž jméno bylo Jairus, a ten byl kníže školy. A padna k nohám Ježíšovým, prosil ho, aby všel do domu jeho."],[42,"Protože měl dceru jedinou, asi ve dvanácti letech, a ta umírala. A když šel, tiskli ho zástupové."],[43,"žena, kteráž nemoc svou trpěla od let dvanácti, a byla na lékaře vynaložila celý statek, a od žádného nemohla uzdravena býti,"],[44,"Přistoupivši po zadu, dotkla se podolka oděvy jeho, a hned přestala nemoc hoí."],[45,"řekl Ježíš: Kdo je, ješto se mne dotekl? A když všichni zapírali, řekl Petr, a kteříž s ním byli: Mistře, zástupové tebe tisknou a tlačí, a pravíš: Kdo se mne dotekl?"],[46,"řekl Ježíš: Dotekl se mne někdo, nebo poznal jsem já, že moc ode mne vyšla."],[47,"viduci ta žena, že by tajno nebylo, třesuci se, přistoupila a padla před ním, a pro kterou příčinu dotkla se ho, pověděla mu přede vším lidem, a jak je hned uzdravena."],[48,"on řekl jí: Dobré mysli buď, dcero, víra tvá tebe uzdravila. Jdiž u pokoji."],[49,"když on ještě mluvil, přišel jeden od knížete školy, řka mu: Umřela dcera tvá, nezaměstknávej Mistra."],[50,"Ale Ježíš uslyšav to, odpověděl mu: Neboj se, věř toliko, a zdrávať bude."],[51,"všel do domu, nedopustil s sebou vjíti žádnému, než Petrovi a Jakubovi a Janovi, a otci a mateři té děvečky."],[52,"Plakali jí pak všichni a kvílili. A on řekl: Neplačtež. Neumřelať, ale spí."],[53,"posmívali se mu, vědouce, že umřela."],[54,"On pak vyhnav ven všecky, a ujav ruku hoí, zvolal, řka: Děvečko, vstaň."],[55,"navrátil se duch hoí, a vstala hned. A kázal jí dáti jísti."],[56,"divili se náramně rodičové hoí. A on jim kázal, aby žádnému nepravili o tom, co se bylo stalo."]]}];

LUKE_SECTIONS["9"] = [{"title":"Vyslání Dvanácti","range":"Lk 9,1–6","thoughts":[],"verses":[[1,"svolav dvanácte učedníků svých, dal jim sílu a moc nad všelikým ďábelstvím, a aby neduhy uzdravovali."],[2,"poslal je, aby kázali království Boží, a uzdravovali nemocné."],[3,"řekl jim: Nic nebeřte na tu cestu, ani hůlky, ani mošny, ani chleba, ani peněz, ani po dvou sukních mívejte."],[4,"do kteréhožkoli domu vešli byste, tu zůstaňte, a odtud vyjděte."],[5,"kteříž by vás koli nepřijali, vyjdouce z města toho, také i ten prach z noh svých vyrazte na svědectví proti nim."],[6,"vyšelše, chodili po městečkách kolem, zvěstujíce evangelium, a uzdravujíce všudy."]]},{"title":"Herodes slyší o Ježíšovi","range":"Lk 9,7–9","thoughts":[],"verses":[[7,"Uslyšel pak Heródes čtvrták o všech věcech, kteréž se dály od něj. A rozjímal to v mysli své, proto že bylo praveno od některých, že by Jan vstal z mrtvých,"],[8,"od jiných, že by se Eliáš zjevil, od některých pak, že by jeden z proroků starých vstal."],[9,"řekl Heródes: Jana jsem já sťal. Kdož pak je tento, o kterémž já slyším takové věci? A žádostiv byl ho viděti."]]},{"title":"Nasycení pěti tisíc","range":"Lk 9,10–17","thoughts":[],"verses":[[10,"Vrátivše se pak apoštolé, vypravovali mu, cožkoli činili. A pojav je, odšel soukromí na místo pusté města řečeného Betsaida."],[11,"Zvěděvše pak zástupové, šli za ním; i přijal je, a mluvil jim o království Božím, a ty, kteříž uzdravení potřebovali, uzdravoval."],[12,"Den pak počal se nachylovati. A přistoupivše dvanácte, řekli mu: Propusť zástupy, ať rozejdouce se do městeček okolních a do vesnic, jdou a hledají pokrmů, nebo jsme tuto na místě pustém."],[13,"řekl jim: Dejte vy jim jísti. A oni řekli: Nemámeť víc než pět chlebů a dvě rybě, leč bychom my snad šli a nakoupili na tento celý lid pokrmů?"],[14,"Protože bylo mužů okolo pěti tisíců. A řekl učedníkům svým. Rozkažte se jim posaditi v každém řadu po padesáti."],[15,"učinili tak, a posadili se všichni."],[16,"vzav těch pět chlebů a ty dvě rybě, vzhlédl v nebe, a dobrořečil jim, i lámal, a rozdával učedníkům, aby kladli před zástup."],[17,"jedli, a nasyceni jsou všichni. A sebráno je, což jim bylo ostalo drobtů, dvanácte košů."]]},{"title":"Petrovo vyznání","range":"Lk 9,18–21","thoughts":[],"verses":[[18,"stalo se, když se on modlil obzvláštně, že byli s ním učedlníci. A otázal se jich, řka: Kým mne praví býti zástupové?"],[19,"oni odpověděvše, řekli: Janem Křtitelem, a jiní Eliášem, jiní pak, že prorok jeden z starých vstal."],[20,"řekl jim: Vy pak kým mne býti říkáte? Odpověděv Petr, řekl: Krista toho Božího."],[21,"on s pohrůžkou jim přikázal, aby toho žádnému nepravili,"]]},{"title":"První předpověď utrpení","range":"Lk 9,22–27","thoughts":[],"verses":[[22,"Pravě: Že Syn člověka musí mnoho trpěti, a potupen býti od starších a od předních kněží {biskupů} i od zákonníků, a zamordován býti, a třetího dne z mrtvých vstáti."],[23,"řekl všechněm: Chce-li kdo přijíti za mnou, zapři sám sebe, a beř svůj kříž na každý den, a následuj mne."],[24,"Protože kdož bude chtíti duši svou zachovati, ztratíť ji; a kdož ztratí duši svou pro mne, tenť ji zachová,"],[25,"Protože co je platno člověku, by celý svět získal, kdyby sám sebe ztratil, aneb sám sebe zmrhal?"],[26,"Protože kdož by se za mne styděl a za mé řeči, za tohoť se Syn člověka styděti bude, když přijde v slávě své a Otcově i svatých andělů."],[27,"Ale říkámť vám jistě: Jsou někteří z stojících tuto, kteříž neokusí smrti, až uzří království Boží."]]},{"title":"Proměnění na hoře","range":"Lk 9,28–36","thoughts":[],"verses":[[28,"stalo se po těch řečech, jako po osmi dnech, že vzav s sebou Petra a Jakuba a Jana, vstoupil na horu, aby se modlil."],[29,"když se modlil, učiněna je tvář jeho proměněná, a oděv jeho bílý a stkvoucí."],[30,"aj, dva muži mluvili s ním, a ti byli Mojžíš a Eliáš."],[31,"Kteříž okázavše se v slávě, vypravovali o smrti jeho, kterouž měl podstoupiti v Jeruzalémě."],[32,"Petr pak a ti, kteříž s ním byli, obtíženi byli snem, a procítivše, viděli slávu jeho a ty dva muže, ani stojí s ním."],[33,"stalo se, když oni odešli od něj, řekl Petr Ježíšovi: Mistře, dobréť je nám zde býti. Protož udělejme tři stánky, tobě jeden, a Mojžíšovi jeden, a Eliášovi jeden, nevěda, co mluví."],[34,"když on to mluvil, stal se oblak, i zastínil je. Báli se pak, když onino vcházeli do oblaku."],[35,"stal se hlas z oblaku řkoucí: Tentoť je ten Syn můj milý, toho poslouchejte."],[36,"když se ten hlas stal, nalezen je Ježíš sám. A oni mlčeli, a nepravili žádnému v těch dnech ničeho z těch věcí, kteréž viděli."]]},{"title":"Uzdravení posedlého chlapce","range":"Lk 9,37–43","thoughts":[],"verses":[[37,"Stalo se pak druhého dne, když sstupovali s hory, potkal ho zástup mnohý."],[38,"aj, muž z zástupu zvolal, řka: Mistře, prosím tebe, vzhlédni na syna mého, neboť jediného toho mám."],[39,"aj, duch ho napadá, a on i hned křičí, a lomcuje jím slinícím se, a nesnadně odchází od něj, sápaje jím."],[40,"prosil jsem učedníků tvých, aby ho vyvrhli, ale nemohli."],[41,"odpověděv Ježíš, řekl: Ó pokolení nevěrné a převrácené, dokudž budu u vás, a snášeti budu vás? Přiveď sem syna svého."],[42,"v tom, když on přicházel, porazil ho ďábel, a lomcoval jím. A přimluvil duchu nečistému Ježíš, a uzdravil toho mládence, a navrátil ho otci jeho."],[43,"děsili se všichni nad velikomocností Božskou. A když se všichni divili všem věcem, kteréž činil Ježíš, řekl učedníkům svým:"]]},{"title":"Druhá předpověď utrpení","range":"Lk 9,44–45","thoughts":[],"verses":[[44,"Složte vy v uších svých řeči tyto, neboť Syn člověka bude vydán v ruce lidské."],[45,"Ale oni nesrozuměli slovu tomu, a bylo před nimi skryto, aby nevyrozuměli mu. A nesměli se ho otázati o tom slovu."]]},{"title":"Kdo je největší","range":"Lk 9,46–50","thoughts":[],"verses":[[46,"vznikla mezi nimi hádka o to, kdo by z nich byl největší."],[47,"Ježíš pak když viděl přemyšlování srdce jejich, vzav řekltě, postavil je podlé sebe,"],[48,"řekl jim: Kdožkoli přijal by řekltě toto ve jménu mém, mneť přijímá; a kdož by koli mne přijal, přijímá toho, kterýž mne poslal. Protože kdožť je nejmenší mezi všemi vámi, tenť bude veliký."],[49,"odpověděv Jan, řekl: Mistře, viděli jsme jednoho, an ve jménu tvém ďábly vymítá; i bránili jsme mu, proto že nechodí s námi."],[50,"dí mu Ježíš: Nebraňtež. Protože kdoť není proti nám, s námiť je."]]},{"title":"Cesta do Jeruzaléma","range":"Lk 9,51–56","thoughts":[],"verses":[[51,"stalo se, když se doplnili dnové vzetí jeho zhůru, že on se na tom ustavil, aby šel do Jeruzaléma."],[52,"poslal posly před sebou. A oni když šli, vešli do městečka Samaritánského, aby mu připravili."],[53,"Ale nepřijali ho, proto že oblíčej jeho byl obrácen k jití do Jeruzaléma."],[54,"když vidělše to učedlníci jeho Jakub a Jan, řekli: Pane, chceš-li, ať řeklme, aby oheň sstoupil s nebe, a spálil je, jako i Eliáš udělal?"],[55,"Ale obrátiv se, potrestal jich, řka: Nevíte, čího jste vy duchu."],[56,"Syn zajisté člověka nepřišel zatracovati duší lidských, ale aby spasil. A odešli do jiného městečka."]]},{"title":"Následování Ježíše","range":"Lk 9,57–62","thoughts":[],"verses":[[57,"Stalo se pak, když šli, že řekl mu na cestě jeden: Pane, půjdu za tebou, kam se koli obrátíš."],[58,"řekl mu Ježíš: Lišky doupata mají, a ptáci nebeští hnízda, ale Syn člověka nemá, kde by hlavu sklonil."],[59,"řekl jinému: Poď za mnou. Ale on řekl: Pane, dopusť mi prvé jíti a pochovati otce mého."],[60,"dí mu Ježíš: Nech ať mrtví pochovávají mrtvé své, ale ty jda, zvěstuj království Boží."],[61,"řekl znovu jiný: Půjdu za tebou, Pane, ale prvé dopusť mi, ať se rozžehnám s těmi, kteříž jsou v domě mém."],[62,"Řekl mu Ježíš: Žádný, kdož vztáhna ruku svou k pluhu, ohlídal by se nazpět, není způsobný k království Božímu."]]}];

LUKE_SECTIONS["10"] = [{"title":"Vyslání sedmdesáti","range":"Lk 10,1–16","thoughts":[],"verses":[[1,"pak vyvolil Pán i jiných sedmdesát, a poslal je po dvou před tváří svou do každého města i místa, kamž měl sám přijíti."],[2,"řekl jim: Žeň zajisté je mnohá, ale dělníků málo. Protož proste Pána žně, ať vypudí dělníky na žeň svou."],[3,"Jdětež. Hle, já posílám vás jako berany mezi vlky."],[4,"Nenostež pytlíka, ani mošny, ani obuvi, a žádného na cestě nepozdravujte."],[5,"do kteréhožkoli domu vejdete, nejprvé rcete: Pokoj tomuto domu."],[6,"bude-liť tu syn pokoje, odpočineť na něm pokoj váš; pakli nic, k vámť se navrátí."],[7,"v témž domu ostaňte, jedouce a pijíce, což u nich je, nebo hoden je dělník mzdy své. Nechoďtež z domu do domu."],[8,"Ale do kteréhožkoli města vešli byste, a přijali by vás, jezte, což před vás předloží."],[9,"uzdravujte nemocné, kteříž by v něm byli, a rcete jim: Přiblížiloť se k vám království Boží."],[10,"do kteréhožkoli města vešli byste, a nepřijali by vás, vyjdouce na ulice jeho, rcetež:"],[11,"Také i ten prach, kterýž se přichytil nás z města vašeho, vyrážíme na vás. Ale však to vězte, žeť se je přiblížilo k vám království Boží."],[12,"Pravím zajisté vám, že Sodomským v onen den lehčeji bude než tomu městu."],[13,"Běda tobě Korozaim, běda tobě Betsaido. Protože kdyby v Týru a v Sidonu činěni byli divové ti, kteříž v vás činěni jsou, dávno by v žíni a v popele sedíce, pokání činili."],[14,"protož Týru a Sidonu lehčeji bude na soudu nežli vám."],[15,"ty Kafarnaum, kteréž jsi až do nebe zvýšeno, až do pekla sníženo budeš."],[16,"Kdož vás slyší, mne slyší; a kdo vámi pohrdá, mnou pohrdá; kdož pak mnou pohrdá, pohrdáť tím, kdož mne poslal."]]},{"title":"Návrat učedníků","range":"Lk 10,17–24","thoughts":[],"verses":[[17,"navrátilo se s radostí těch sedmdesáte, řkouce: Pane, také i ďáblové se nám poddávají ve jménu tvém."],[18,"řekl jim: Viděl jsem satana jako blesk padajícího s nebe."],[19,"Hle, dávámť vám moc šlapati na hady a na štíry i na všelikou moc nepřítele, a nic vám neuškodí."],[20,"však z toho se neradujte, že se vám poddávají duchové, ale raději se radujte, že jména vaše napsána jsou v nebesích."],[21,"V tu hodinu rozveselil se v duchu Ježíš, a řekl: Chválím tě, Otče, Pane nebe i země, že jsi tyto věci skryl před moudrými a opatrnými, a zjevils je nemluvňátkům. Ovšem, Otče, nebo se tak líbilo před tebou."],[22,"Všecky věci dány jsou mi od Otce mého, a žádný neví, kdo by byl Syn, jediné Otec, a kdo by byl Otec, jediné Syn, a komuž by chtěl Syn zjeviti."],[23,"obrátiv se k učedníkům obzvláštně, řekl: Blahoslavené oči, kteréž vidí, co vy vidíte."],[24,"Protože říkám vám, že mnozí proroci i králové chtěli viděti, což vy vidíte, ale neviděli, a slyšeti, což vy slyšíte, ale neslyšeli."]]},{"title":"Milosrdný Samařan","range":"Lk 10,25–37","thoughts":[],"verses":[[25,"aj, jeden zákonník vstal, pokoušeje ho, a řka: Mistře, co čině, život věčný dědičně obdržím?"],[26,"on řekl mu: V zákoně co je psáno? Kterak čteš?"],[27,"on odpověděv, řekl: Milovati budeš Pána Boha svého ze všeho srdce svého, a ze vší duše své, a ze vší síly své, i ze vší mysli své, a bližního svého jako sebe samého."],[28,"řekl mu: Právě jsi odpověděl. To čiň, a živ budeš."],[29,"On pak chtěje se sám ospravedlniti, dí Ježíšovi: A kdo je můj bližní?"],[30,"odpověděv Ježíš, řekl: Člověk jeden šel z Jeruzaléma do Jericho, i upadl mezi lotry. Kteříž obloupivše ho a zranivše, odešli, odpolu živého nechavše."],[31,"přihodilo se, že kněz jeden šel touž cestou, a když uviděl ho, pominul."],[32,"Též i Levíta přišel až k tomu místu, a když uviděl ho, pominul."],[33,"Samaritán pak jeden, cestou se ubíraje, přišel až k němu, a když uviděl ho, milosrdenstvím hnut je."],[34,"přistoupiv, uvázal rány jeho, naliv oleje a vína, a vloživ ho na hovado své, vedl do hospody, a péči o něj měl."],[35,"Druhého pak dne odjíti měl, vyňav dva peníze, dal hospodáři, a řekl mu: Měj o něj péči, a cožkoli nad to vynaložíš, já když se vrátím, zaplatím tobě."],[36,"Kdo tedy z těch tří zdá se tobě bližním býti tomu, kterýž upadl mezi lotry?"],[37,"on řekl: Ten, kterýž prokázal milosrdenství nad ním. A řekl mu Ježíš: Jdi, i ty učiň též."]]},{"title":"Marie a Marta","range":"Lk 10,38–42","thoughts":[],"verses":[[38,"stalo se, když šli, že on všel do jednoho městečka. Žena pak jedna, jménem Marta, přijala ho do domu svého."],[39,"ta měla sestru, jménem Marii, kteráž seděci u noh Ježíšových, poslouchala slova jeho."],[40,"Ale Marta pečlivá byla při mnohé službě. Kteráž přistoupivši, řekla: Pane, nemáš-liž o to péče, že sestra má nechala mne samé sloužiti? Protož rci jí, ať mi pomůž."],[41,"odpověděv, řekl jí Ježíš: Marta, Marta, pečlivá jsi, a rmoutíš se při mnohých věcech."],[42,"Ale jednohoť je potřebí. Mariať dobrou stránku vyvolila, kteráž nebude odjata od ní."]]}];

LUKE_SECTIONS["11"] = [{"title":"Modlitba Páně","range":"Lk 11,1–4","thoughts":[],"verses":[[1,"stalo se, když se na jednom místě modlil, když přestal, řekl mu jeden z učedníků jeho: Pane, nauč nás modliti se, jako i Jan učil učedníky své."],[2,"řekl jim: Když se modlíte, říkejte: Otče náš, kterýž jsi v nebesích, posvěť se jméno tvé. Přiď království tvé. Buď vůle tvá, jako v nebi tak i na zemi."],[3,"Chléb náš vezdejší dávej nám každého dne."],[4,"odpusť nám hříchy naše, nebo i my odpouštíme všelikému vinníku svému. A neuvoď nás v pokušení, ale zbav nás od zlého."]]},{"title":"Vytrvalost v modlitbě","range":"Lk 11,5–13","thoughts":[],"verses":[[5,"řekl jim: Kdo z vás bude míti přítele, a půjde k němu o půlnoci, a dí mu: Příteli, půjč mi tří chlebů."],[6,"Protože přítel můj přišel s cesty ke mně, a nemám, co bych předložil před něj."],[7,"on vnitř když byl, odpověděl by: Nečiň mi nevole; dvéře již zavříny, a řekltky mé se mnou jsou v pokoji. Nemohuť vstáti a dáti tobě."],[8,"Pravím vám: Ačť nedá mu, vstana, proto že je přítel jeho, ale však pro nezbednost jeho vstana, dá mu, kolikžkoli potřebuje."],[9,"jáť říkám vám: Proste, a budeť vám dáno; hledejte, a naleznete; tlucte, a budeť vám otevříno."],[10,"Protože každý, kdož prosí, béře; a kdož hledá, nalézá; a tomu, kdož tluče, bude otevříno."],[11,"Kterého pak z vás otce prosil by syn za chléb, zda kamene podá mu? Aneb za rybu, zda místo ryby dá mu hada?"],[12,"Aneb prosil-li by za vejce, zda podá mu štíra?"],[13,"Poněvadž tedy vy, jsouce zlí, umíte dobré dary dávati dětem svým, čím více Otec váš nebeský dá Ducha svatého těm, kteříž ho prosí?"]]},{"title":"Ježíš a Belzebul","range":"Lk 11,14–26","thoughts":[],"verses":[[14,"vymítal dábelství, a to bylo němé. Stalo se pak, když vyšlo ďábelství, mluvil ten němý. A divili se zástupové."],[15,"Ale někteří z nich říkali: Skrze Belzebuba, kníže ďábelské, vymítá ďábly."],[16,"jiní pokoušejíce, znamení od něj hledali s nebe."],[17,"Ale on znaje myšlení jejich, řekl jim: Každé království samo v sobě rozdělené pustne, i dům rozdvojený padá."],[18,"Jestližeť je pak i satan proti sobě rozdělen, jakž stane království jeho? Protože říkáte, že já skrze Belzebuba vymítám ďábly."],[19,"Jestliže já skrze Belzebuba vymítám ďábly, synové vaši skrze koho vymítají? Protož oni soudcové vaši budou."],[20,"Pakliť prstem Božím vymítám ďábly, jistěť přišlo k vám království Boží."],[21,"Když silný oděnec ostříhá síně své, v pokoji jsou všecky věci, kteréž má."],[22,"Pakli by silnější než on přijda, přemohl ho, všechna odění jeho odejme, v něž úfal, a loupeže jeho rozdělí."],[23,"Kdož není se mnou, proti mně je; a kdož neshromažďuje se mnou, rozptylujeť."],[24,"Když nečistý duch vyjde od člověka, chodí po místech suchých, hledaje odpočinutí. A nenalezna, dí: Vrátím se do domu svého, odkudž jsem vyšel."],[25,"přijda, nalezne vymetený a ozdobený."],[26,"Tehdy jde, a přijme k sobě jiných sedm duchů horších, než je sám, a vejdouce, přebývají tam. A jsou poslední věci člověka toho horší nežli první."]]},{"title":"Pravé blahoslavenství","range":"Lk 11,27–28","thoughts":[],"verses":[[27,"stalo se, když on to mluvil, že pozdvihši hlasu jedna žena z zástupu, řekla mu: Blahoslavený život, kterýž tebe nosil, a prsy, kterýchž jsi požíval."],[28,"On pak řekl: Anobrž blahoslavení, kteříž slyší slovo Boží, a ostříhají jeho."]]},{"title":"Znamení Jonášovo","range":"Lk 11,29–32","thoughts":[],"verses":[[29,"když se zástupové scházeli k němu, počal praviti: Pokolení toto nešlechetné je. Znamení vyhledává, ale znamení mu nebude dáno, než znamení to Jonáše proroka."],[30,"Protože jakož Jonáš učiněn byl znamením Ninivitským, takť bude i Syn člověka pokolení tomuto."],[31,"Královna od poledne stane na soudu s muži pokolení tohoto, a odsoudí je. Protože přijela od končin země, aby slyšela moudrost Šalomounovu, a aj, více než Šalomoun tuto."],[32,"Muži Ninivitští povstanou na soudu s pokolením tímto, a odsoudí je. Protože činili pokání k kázaní Jonášovu, a aj, více nežli Jonáš tuto."]]},{"title":"Lampa těla","range":"Lk 11,33–36","thoughts":[],"verses":[[33,"Žádný rozsvítě svíci, nepostaví jí do skrýše, ani pod kbelec, ale na svícen, aby ti, kteříž vcházejí, světlo viděli."],[34,"Svíce těla je oko. Když by tedy oko tvé sprostné bylo, i tělo tvé všechno bude světlé; a pakliť bude nešlechetné, i tělo tvé tmavé bude."],[35,"Viziž tedy, aby světlo, kteréž je v tobě, nebylo tmou."],[36,"Pakli celé tělo tvé světlé bude, nemaje žádné částky tmavé, budeť všechno tak světlé, že tě jako svíce bleskem osvítí."]]},{"title":"Běda farizeům a zákoníkům","range":"Lk 11,37–54","thoughts":[],"verses":[[37,"když on mluvil, prosil ho jeden farizeus, aby obědval u něj. A všel, posadil se za stůl."],[38,"Farizeus pak když viděl to, podivil se, že se neumyl před obědem."],[39,"řekl Pán mu: Nyní vy farizeové povrchu konvice a misy čistíte, ale to, což vnitř je u vás, plno je loupeže a nešlechetnosti."],[40,"Blázni, zdaž ten, kterýž udělal, což zevnitř je, neučinil také i toho, což je vnitř?"],[41,"Ale však i z toho, což máte, dávejte almužnu, a aj, všecky věci vaše čisté budou."],[42,"Ale běda vám farizeům, že desátky dáváte z máty a z routy a ze všeliké byliny, ale opouštíte soud a lásku Boží. Tyto věci měli jste činiti, a oněch neopouštěti."],[43,"Běda vám farizeům, nebo milujete první místa v školách a pozdravování na trzích."],[44,"Běda vám, zákonníci a farizeové pokrytci, nebo jste jako hrobové nepatrní, a lidé chodíce po nich, nevědí."],[45,"odpověděv jeden z zákonníků, řekl mu: Mistře, tyto věci mluvě, i nám také lehkost činíš."],[46,"on řekl: A vám zákonníkům běda, nebo obtěžujete lidi břemeny nesnesitelnými, a sami se těch břemen jedním prstem nedotýkáte."],[47,"Běda vám, proto že vzděláváte hroby prorocké, kteréž otcové vaši zmordovali."],[48,"tak osvědčujete a potvrzujete skutků otců svých. Protože oni zajisté zmordovali je, vy pak vzděláváte hroby jejich."],[49,"Protož i Moudrost Boží řekla: Pošliť k nim proroky a apoštoly, a z těch některé mordovati budou, a jiné vyháněti,"],[50,"Aby požádáno bylo od tohoto pokolení krve všech proroků, kteráž vylita je od ustanovení světa,"],[51,"Od krve Abelovy až do krve Zachariášovy, kterýž zahynul mezi oltářem a chrámem. Jistě, říkám vám, požádáno jí bude od pokolení tohoto."],[52,"Běda vám zákonníkům, nebo jste vzali klíč umění; sami jste nevešli, a těm, kteříž vcházeli, zbránili jste."],[53,"když jim to mluvil, počali zákonníci a farizeové přísně na něj dotírati, a k mnohým řečem příčiny mu dávati."],[54,"Úklady činíce mu, a hledajíce popadnouti něco z úst jeho, aby ho obžalovali."]]}];
LUKE_SECTIONS["12"] = [{"title":"Varování před pokrytectvím","range":"Lk 12,1–12","thoughts":[],"verses":[[1,"v tom, když se na tisíce lidu sešlo, tak že jedni druhé velmi tlačili, počal mluviti k učedníkům svým: Nejpředněji se varujte od kvasu farizeů, kterýž je pokrytství."],[2,"Protožeť nic není skrytého, což by nemělo býti zjeveno; aniž je co tajného, ješto by nemělo býti zvěřeklno."],[3,"Protož to, co jste říkali ve tmách, bude na světle slyšáno, a co jste v uši šeptali v pokojích, hlásánoť bude na střechách."],[4,"Pravím pak vám přátelům svým: Nestrachujte se těch, kteříž tělo zabíhoí, a potom nemají, co by více učinili."],[5,"Ale ukážiť vám, koho se máte báti: Bojte se toho, kterýž, když zabije, má moc uvrci do pekelného ohně. Jistě říkám vám, toho se bojte."],[6,"Zdaliž nebývá pět vrabečků prodáváno za dva penížky? A jeden z nich není v zapomenutí před Bohem."],[7,"Nýbrž i vlasové hlavy vaší všichni v počtu jsou. Protož nebojtež se, mnohoť vy vrabečků převyšujete."],[8,"Pravímť pak vám: Každý kdož by koli vyznal mne před lidmi, i Syn člověka vyzná ho před anděly Božími."],[9,"Kdož by mne pak zapřel před lidmi, zapřínť bude před anděly Božími."],[10,"každý kdož dí slovo proti Synu člověka, bude mu odpuštěno, ale tomu, kdož by se Duchu svatému rouhal, nebudeť odpuštěno."],[11,"Když pak vás voditi budou do škol a k vládařům a k mocným, nepečujte, jak aneb co byste odpovídali, aneb co byste mluvili."],[12,"Duch svatý zajisté naučí vás v tu hodinu,co byste měli mluviti."]]},{"title":"Podobenství o bohatém bláznu","range":"Lk 12,13–21","thoughts":[],"verses":[[13,"řekl mu jeden z zástupu: Mistře, rci bratru mému, ať rozdělí se mnou dědictví."],[14,"on řekl mu: Člověče, kdo mne ustavil soudcím aneb děličem nad vámi?"],[15,"řekl jim: Viztež a vystříhejte se od lakomství; neboť ne v rozhojnění statku něčího život jeho záleží."],[16,"Pověděl pak jim podobenství, řka: Člověka jednoho bohatého hojné úrody pole přineslo."],[17,"přemyšloval sám v sobě, řka: Co udělám? Protože nemám, kde bych shromáždil úrody své."],[18,"řekl: Toto udělám: Zbořím stodoly své, a větších nastavím, a tu shromážřeklm všecky své úrody i zboží svá."],[19,"řeklm duši své: Duše, máš mnoho statku složeného za mnohá léta, odpočívej, jez, pí, měj dobrou vůli."],[20,"řekl mu Bůh: Ó blázne, této noci požádají duše tvé od tebe, a to, cožs připravil, čí bude?"],[21,"Takť je, kdož sobě poklady shromažďuje, a není v Bohu bohatý."]]},{"title":"Nestarejte se úzkostlivě","range":"Lk 12,22–34","thoughts":[],"verses":[[22,"Řekl pak učedníkům svým: Protož říkám vám: Nebuďte pečliví o život svůj, co byste jedli, ani o tělo, čím byste se odívali."],[23,"Život více je nežli pokrm, i tělo nežli oděv."],[24,"Patřte na havrany, žeť nesejí, ani nežnou, a nemají špižírny {pivnice}, ani stodoly a však Bůh živí je. A čím v větší vážnosti jste vy než ptactvo?"],[25,"kdož pak z vás pečlivě mysle, můž přidati ku postavě své loket jeden?"],[26,"Poněvadž tedy nemůžete s to býti, což nejmenšího je, proč se o jiné věci staráte?"],[27,"Patřte na kvítí, jak rostou, nedělají, ani předou, říkámť pak vám, že ani Šalomoun ve vší slávě své nebyl tak odín, jako jedno z těchto."],[28,"poněvadž trávu, kteráž dnes na poli je, a zítra do peci uvržena bývá, Bůh tak odívá, čím více vás, ó malé víry?"],[29,"vy nehledejtež toho, co byste jedli, aneb co byste pili, aniž o to roztržité mysli buďte."],[30,"Protože těch všech věcí národové světa tohoto hledají, Otec pak váš ví, že těch věcí potřebujete."],[31,"Ale raději hledejte království Božího, a tyto všecky věci budou vám přidány."],[32,"Neboj se, ó maličké stádce, neboť se zalíbilo Otci vašemu dáti vám království."],[33,"Prodávejte statky své, a dávejte almužnu. Dělejte sobě pytlíky, kteříž nevetšejí, poklad, kterýž nehyne v nebesích, kdež zloděj dojíti nemůž, aniž mol kazí."],[34,"Protože kdež je poklad váš, tuť bude i srdce vaše."]]},{"title":"Buďte připraveni","range":"Lk 12,35–48","thoughts":[],"verses":[[35,"Buďtež bedra vaše přepásaná, a svíce hořící."],[36,"vy podobni lidem očekávajícím Pána svého, až by se vrátil z svadby, aby hned, jakž by přišel a potloukl, otevřeli mu."],[37,"Blaze služebníkům těm,kteréž přijda Pán, nalezl by, a oni bdí. Amen, říkám vám, že přepáše se, a vsadí je za stůl, a chodě, bude jim sloužiti."],[38,"přišel-liť by v druhé bdění, a pakliť by v třetím bdění přišel, a tak je nalezl, blahoslavení jsou ti služebníci,"],[39,"Toto pak vězte, že byť věděl hospodář, v kterou by hodinu měl zloděj přijíti, bděl by zajisté, a nedal by podkopati domu svého."],[40,"Protož i vy buďte hotovi, nebo v kterou hodinu nenadějete se, Syn člověka přijde."],[41,"řekl mu Petr: Pane, nám-li pravíš toto podobenství, čili všechněm?"],[42,"dí Pán: Kdo je věrný šafář a opatrný, jehož by ustanovil pán nad čeledí svou, aby jim v čas dával vyměřený pokrm?"],[43,"Blahoslavený služebník ten, kteréhož, když by přišel pán jeho, nalezne, an tak činí."],[44,"V pravdě říkám vám, že nade vším statkem svým ustanoví ho."],[45,"Pakli by řekl služebník ten v srdci svém: Prodlévá přijíti pán můj, i počal by bíti služebníky a děvky, a jísti a píti i opíjeti se:"],[46,"Přijdeť pán služebníka toho v den,v kterýž se nenaděje, a v hodinu, kteréž neví. A oddělíť ho, a řekll jeho položí s nevěrnými."],[47,"Služebník pak ten, kterýž by znal vůli pána svého, a nebyl hotov, a nečinil podlé vůle jeho, bit bude velmi."],[48,"Ale kterýž neznal, a činil hodné věci trestání, bit bude méně. Každému pak, komuž je mnoho dáno, mnoho bude od něj požádáno; a komuť mnoho poručili, víceť požádají od něj."]]},{"title":"Ježíš přináší rozhodnutí","range":"Lk 12,49–53","thoughts":[],"verses":[[49,"Oheň přišel jsem pustiti na zemi, a co chci, jestliže již hoří?"],[50,"Ale křtem mám křtěn býti, a jak jsem ssoužen, dokudž se nevykoná!"],[51,"Což se domníváte, že bych přišel pokoj uvésti na zemi? Nikoli, říkám vám, ale rozdělení."],[52,"Protože již od této chvíle bude jich pět v jednom domě rozděleno, tři proti dvěma, a dva proti třem."],[53,"Bude rozdělen otec proti synu, a syn proti otci, mátě proti dceři, a dcera proti mateři, svegruše proti nevěstě své, a nevěsta proti svegruši své."]]},{"title":"Rozpoznávání času","range":"Lk 12,54–59","thoughts":[],"verses":[[54,"Pravil také i zástupům: Když vídáte oblak, an vzchází od západu, hned říkáte: Příval jde, a tak bývá."],[55,"když od poledne vítr věje, říkáte: Bude horko, a býváť."],[56,"Pokrytci, způsob země i nebe umíte souditi, a jakž pak tohoto času nesoudíte?"],[57,"Ano proč i sami od sebe nesoudíte, což spravedlivého?"],[58,"Když pak jdeš s protivníkem svým k vrchnosti, na cestě přičiň se o to, abys byl zproštěn od něj, aby snad netáhl tebe k soudci, a soudce dal by tebe biřici, a biřic vsadil by tě do žaláře."],[59,"Pravím tobě: Nevyjdeš odtud, dokudž bys i toho posledního haléře nenavrátil."]]}];

LUKE_SECTIONS["13"] = [{"title":"Výzva k obrácení","range":"Lk 13,1–9","thoughts":[],"verses":[[1,"Byli pak tu přítomní času toho někteří, vypravujíce mu o Galilejských, kterýchž krev Pilát smísil s obětmi jejich."],[2,"odpověděv Ježíš, řekl jim: Co mníte, že ti Galilejští byli větší hříšníci nežli všichni Galilejští, že takové věci trpěli?"],[3,"Nikoli, říkám vám. Nýbrž nebudete-li pokání činiti, všichni též zahynete."],[4,"Aneb oněch osmnácte, na kteréž upadla věže v Siloe, a zbila je, zda se domníváte, že by oni vinni byli nad všecky lidi, přebývající v Jeruzalémě?"],[5,"Nikoli, říkám vám. Nýbrž nebudete-li pokání činiti, všichni též zahynete."],[6,"Pověděl pak toto podobenství: Člověk jeden měl strom fíkový štípený na vinici své. A přišel, hledaje ovoce na něm, ale nenalezl."],[7,"řekl vinaři: Hle, po tři léta přicházím, hledaje ovoce na tom fíku, ale nenalézám. Vytniž ho. Proč i tu zemi darmo kazí?"],[8,"On pak odpověděv, řekl mu: Pane, ponechejž ho i tohoto léta, ažť ho okopám a ohnojím,"],[9,"Zdali by nesl ovoce. Pakliť neponese, potom vytneš ho."]]},{"title":"Uzdravení ženy v sobotu","range":"Lk 13,10–17","thoughts":[],"verses":[[10,"Učil pak v jedné škole v sobotu."],[11,"aj, byla tu žena, kteráž měla ducha nemoci osmnáct let, a byla sklíčena, a nijakž se nemohla zpřímiti."],[12,"když uviděl ji Ježíš, zavolal jí k sobě, a řekl jí: Ženo, zproštěna jsi od nemoci své."],[13,"vložil na ni ruce, a i hned zdvihla se, a velebila Boha."],[14,"kníže školní odpověděv, hněvaje se proto, že v den sobotní uzdravoval Ježíš, řekl zástupu: Šest dní je, v nichž náleží dělati; protož v těch přicházejíce, buďte uzdravováni, a ne v den sobotní."],[15,"odpověděv mu Pán, řekl: Pokrytče, zda jeden každý z vás v sobotu neodvazuje vola svého neb osla od jeslí, a nevodí napájeti?"],[16,"Tato pak dcera Abrahamova, kterouž byl svázal satan, aj, již osmnácte let, což neměla býti rozvázána z svazku tohoto v den sobotní?"],[17,"když on to pověděl, zastyděli se všichni protivníci jeho, ale celý lid radoval se ze všech těch slavných skutků, kteříž se dáli od něj."]]},{"title":"Hořčičné zrno a kvas","range":"Lk 13,18–21","thoughts":[],"verses":[[18,"řekl: Čemu podobno je království Boží, a k čemu je přirovnám?"],[19,"Podobno je zrnu horčičnému, kteréž vzav člověk, uvrhl do zahrady své. A rostlo, a učiněno je v strom veliký, a ptactvo nebeské hnízda sobě dělali na ratolestech jeho."],[20,"znovu řekl: K čemu připodobním království Boží?"],[21,"Podobno je kvasu, kterýž vzavši žena, zadělala ve třech měřicích mouky, až zkysalo všechno."]]},{"title":"Těsná brána","range":"Lk 13,22–30","thoughts":[],"verses":[[22,"chodil po městech a městečkách, uče, bera se do Jeruzaléma."],[23,"řekl mu jeden: Pane, co nemnozí jsou ti, kteří spaseni býti mají? On pak řekl jim:"],[24,"Snažujte se vcházeti těsnou branou; neboť (říkám vám), mnozí usilovati budou vjíti, ale nebudou moci."],[25,"Když vstane hospodář, a zavře dvéře, a počnete vně státi a tlouci na dvéře, řkouce: Pane, Pane, otevři nám, a on odpovídaje, díť vám: Neznám vás, odkud jste:"],[26,"počnete říci: Jídali jsme a píjeli před tebou, a na ulicech našich jsi učíval."],[27,"dí: Pravím vám, neznám vás, odkud jste. Odejdětež ode mne všichni činitelé nepravosti."],[28,"Tamť bude pláč a škřipení zubů, když uzříte Abrahama, a Izáka, a Jákoba, a všecky proroky v království Božím, sami pak sebe vyhnané ven."],[29,"přijdouť od východu, a od západu, a od půlnoci, i od poledne, a budou stoliti v království Božím."],[30,"aj, jsouť poslední, kteříž budou první, a jsou první, kteříž budou poslední."]]},{"title":"Ježíšův nářek nad Jeruzalémem","range":"Lk 13,31–35","thoughts":[],"verses":[[31,"v ten den přistoupili někteří z farizeů, řkouce mu: Vyjdi, a odejdi odsud, nebo Heródes chce tě zamordovati."],[32,"řekl jim: Jdouce, povězte lišce té: Hle, vymítám ďábly, a uzdravuji dnes a zítra, a třetího dne dokonám."],[33,"Ale však musím dnes a zítra i po zejtří choditi; neboť nelze proroku zahynouti kromě Jeruzaléma."],[34,"Jeruzaléme, Jeruzaléme, ješto morduješ proroky, a kamenuješ ty, kteříž k tobě bývají posláni, kolikrát jsem chtěl shromážditi řekltky tvé, jako slepice kuřátka svá pod křídla? Ale nechtěli jste."],[35,"Hle, zanechán bude vám dům váš pustý. Ale jistě říkám vám, že nikoli mne neuzříte, ažť přijde, když řeklte:Požehnaný, kterýž se béře ve jménu Páně."]]}];

LUKE_SECTIONS["14"] = [{"title":"Uzdravení v sobotu","range":"Lk 14,1–6","thoughts":[],"verses":[[1,"stalo se, když všel Ježíš do domu nějakého knížete farizejského v sobotu, aby jedl chléb, že oni šetřili ho."],[2,"aj, člověk nějaký vodnotelný byl před ním."],[3,"odpověděv Ježíš, dí zákonníkům a fazieům, řka:Sluší-li v sobotu uzdravovati?"],[4,"Oni pak mlčeli. Potom on dosáh jeho, uzdravil a propustil."],[5,"odpověděv jim, řekl:Čí z vás osel aneb vůl upadl by do studnice, a ne i hned by ho vytáhl v den sobotní?"],[6,"nemohli mu na to odpověřeklti."]]},{"title":"Pokora při hostině","range":"Lk 14,7–14","thoughts":[],"verses":[[7,"Pověděl také i pozvaným podobenství, (spatřiv to, jak přední místa vyvolovali), řka jim:"],[8,"Kdybys byl od někoho pozván na svadbu, nesedej na předním místě, aťby snad vzácnější než ty nebyl pozván od něj."],[9,"přijda ten, kterýž tebe i onoho pozval, řekl by tobě:Dej tomuto místo. A tehdy počal bys s hanbou na posledním místě seděti."],[10,"Ale když bys byl pozván, jda, posaď se na posledním místě. A kdyby přišel ten, kterýž tebe pozval, řekl by tobě:Příteli, posedni výše, tedy budeš míti chválu před spolustolícími."],[11,"Protože každý, kdož se povyšuje, bude ponížen; a kdož se ponižuje, bude povýšen."],[12,"Pravil také i tomu, kterýž ho byl pozval:Když činíš oběd neb večeři, nezov přátel svých, ani bratří svých, ani příbuzných svých, ani sousedů bohatých, aťby snad i oni zase nezvali tebe, a měl bys odplatu."],[13,"Ale když činíš hody, povolej chudých, chromých, kulhavých, slepých,"],[14,"blahoslavený budeš. Protožeť nemají, odkud by odplatili tobě, ale budeť odplaceno při vzkříšení spravedlivých."]]},{"title":"Podobenství o velké hostině","range":"Lk 14,15–24","thoughts":[],"verses":[[15,"uslyšav to jeden z spolupřísedících, řekl mu:Blahoslavený, kdož jí chléb v království Božím."],[16,"On pak řekl mu:Člověk nějaký udělal večeři velikou, a pozval mnohých."],[17,"poslal služebníka svého v hodinu večeře, aby řekl pozvaným:Pojďte, nebo již připraveno je všechno."],[18,"počali se všichni jednomyslně vymlouvati. První řekl mu:Ves jsem koupil, i musím vyjíti a shlédnouti ji; prosím tebe, vymluv mne."],[19,"druhý řekl:Patero spřežení volů koupil jsem, a jdu, abych jich zkusil; prosím tebe, vymluv mne."],[20,"jiný dí:Ženu jsem pojal, a protož nemohu přijíti."],[21,"navrátiv se ten služebník, zvěstoval ty věci pánu svému. Potom rozhněvav se hospodář, řekl služebníku svému:Vyjdi rychle na rynky a na ulice města, a chudé, i chromé, i kulhavé, a slepé uveď sem."],[22,"řekl služebník:Pane, stalo se, jakž jsi rozkázal, a ještěť místo je."],[23,"řekl pán služebníku:Vyjdiž na cesty a mezi ploty, a přinuť vjíti, ať se naplní dům můj."],[24,"Protože říkámť vám, že žádný z mužů těch, kteříž pozváni byli, neokusí večeře mé."]]},{"title":"Cena následování","range":"Lk 14,25–35","thoughts":[],"verses":[[25,"Šli pak mnozí zástupové s ním. A obrátiv se, řekl jim:"],[26,"Jde-li kdo ke mně, a nemá-li v nenávisti otce svého, i mateře, i ženy, i dětí, i bratří,i sestr, ano i té duše své, nemůž býti mým učedníkem."],[27,"kdokoli nenese kříže svého, a jde za mnou, nemůž býti mým učedníkem."],[28,"Protože kdo z vás je, chtěje stavěti věži, aby prvé sedna, nepočetl nákladu, má-li to, nač by ji dokonal?"],[29,"Aby snad, když by základ položil, a dokonati nemohl, všichni, kteříž by to viděli, nepočali se posmívati mu,"],[30,"Řkouce:Tento člověk počal stavěti, a nemohl dokonati."],[31,"Aneb který král, bera se k boji proti jinému králi, zdaž prvé nesedne, aby se poradil, mohl-li by s desíti tisíci potkati se s tím, kterýž s dvadcíti tisíci táhne proti němu?"],[32,"Sic jinak, když by onen ještě podál od něj byl, pošle posly k němu, žádaje za to, což je ku pokoji."],[33,"Tak zajisté každý z vás, kdož se neodřekne všech věcí, kterýmiž vládne, nemůž býti mým učedníkem."],[34,"Dobráť je sůl. Pakli sůl bude zmařena, čím bude napravena?"],[35,"Ani do země, ani do hnoje se nehodí; ven ji vymítají. Kdo má uši k slyšení, slyš."]]}];

LUKE_SECTIONS["15"] = [{"title":"Ztracená ovce","range":"Lk 15,1–7","thoughts":[],"verses":[[1,"Přibližovali se pak k němu všichni celníki a hříšníci, aby ho slyšeli."],[2,"reptali farizeové a zákonníci, řkouce: Tento hříšníky přijímá, a jí s nimi."],[3,"pověděl jim podobenství toto, řka:"],[4,"Kdyby někdo z vás měl sto ovec, a ztratil by jednu z nich, zdaž by nenechal devadesáti devíti na poušti, a nešel k té, kteráž zahynula, až by i nalezl ji?"],[5,"nalezna, vložil by na ramena svá s radostí."],[6,"přijda domů, svolal by přátely a sousedy, řka jim: Spolu radujte se se mnou, nebo jsem nalezl ovci svou, kteráž byla zahynula."],[7,"Pravímť vám, že tak je radost v nebi nad jedním hříšníkem pokání činícím větší, než nad devadesáti devíti spravedlivými, kteříž nepotřebují pokání."]]},{"title":"Ztracená mince","range":"Lk 15,8–10","thoughts":[],"verses":[[8,"Aneb žena některá mělaí grošů deset, ztratila-li by jeden groš, zdaž nezažže svíce, a nemete domu, a nehledá pilně, dokudž nenalezne?"],[9,"když nalezne, svolá přítelkyně a sousedy, řkuci:Spolu radujte se se mnou, nebo jsem nalezla groš, kterýž jsem byla ztratila."],[10,"Takť, říkám vám, že je radost před anděly Božími nad jedním hříšníkem pokání činícím."]]},{"title":"Marnotratný syn","range":"Lk 15,11–32","thoughts":[],"verses":[[11,"Řekl také: Člověk jeden měl dva syny."],[12,"Z nichž mladší řekl otci:Otče, dej mi řekll statku, kterýž mně náleží. A rozdělil jim statek."],[13,"po nemnohých dnech, shromáždiv všechno mladší ten syn, odšel do daleké krajiny, a tam rozmrhal statek svůj, když byl prostopašně živ."],[14,"když všechno utratil, stal se hlad veliký v krajině té, a on počal nouzi trpěti."],[15,"všel, přídržel se jednoho měštěnína krajiny té; a on ho poslal na pole své, aby pásl vepře."],[16,"žádal nasytiti břicho své mlátem, kteréž svině jedly, ale žádný nedával mu."],[17,"Přišel pak sám k sobě, řekl:Jak mnozí nájemníci u otce mého hojnost mají chleba,a já hladem mru!"],[18,"Vstana, půjdu k otci svému, a řeklm mu:Otče, zhřešil jsem proti nebi a před tebou,"],[19,"Aniž jsem hoden více slouti synem tvým. Učiň mne jako jednoho z nájemníků svých."],[20,"vstal, šel k otci svému. A když ještě opodál byl, uviděl ho otec jeho, a milosrdenstvím když byl hnut, přiběh, padl na šíji jeho, a políbil ho."],[21,"řekl mu syn: Otče, zhřešil jsem proti nebi a před tebou, aniž jsem hoden více slouti synem tvým."],[22,"řekl otec služebníkům svým:Přineste to oděv první, a oblecte ho, a dejte prsten na ruku jeho a obuv na nohy."],[23,"přivedouce to tele tučné, zabíte, a hodujíce, buďme veseli."],[24,"Protože tento syn můj byl umřel, a zase ožil; byl zahynul, a nalezen je. A počali veseli býti."],[25,"Byl pak syn jeho starší na poli. A jda, když se přibližoval k domu, uslyšel zpívání a hluk veselících se."],[26,"povolav jednoho z služebníků, otázal se, co by to bylo."],[27,"on řekl mu: Bratr tvůj přišel, i zabil otec tvůj tučné tele, že ho zdravého přijal."],[28,"rozhněval se, a nechtěl vjíti. Otec pak jeho vyšel, prosil ho."],[29,"on odpověděv, řekl otci: Hle, tolik let sloužím tobě, a nikdy jsem přikázaní tvého nepřestoupil, a však nikdy jsi mi nedal kozelce, abych s přátely svými vesel pobyl."],[30,"Ale když syn tvůj tento, kterýž prožral statek tvůj s nevěstkami, přišel, zabils mu to tele tučné."],[31,"on řekl mu: Synu, ty vždycky se mnou jsi, a všecky věci mé jsou tvé."],[32,"Ale veseliti a radovati se náleželo. Protože bratr tvůj tento byl umřel, a zase ožil; zahynul byl, a nalezen je."]]}];

LUKE_SECTIONS["16"] = [{"title":"Podobenství o nepoctivém správci","range":"Lk 16,1–13","thoughts":[],"verses":[[1,"Pravil pak i učedníkům svým: Člověk jeden byl bohatý, kterýž měl šafáře; a ten obžalován je před ním, jako by mrhal statek jeho."],[2,"povolav ho, řekl mu: Což to slyším o tobě? Vydej počet z vládařství svého, nebo již nebudeš moci déle vládnouti."],[3,"dí vládař sám v sobě: Co udělám? Teď pán můj odjímá ode mne vládařství. Kopati nemohu, žebrati se stydím."],[4,"Vím, co udělám, aby, když budu zsazen z vládařství, přijali mne do svých domů."],[5,"zavolav jednoho každého dlužníka pána svého, řekl prvnímu: Jaks mnoho dlužen pánu mému?"],[6,"on řekl: Sto tun oleje. A řekl mu: Vezmi rejistra svá, a sedna rychle, napiš padesát."],[7,"druhému řekl: Ty pak jaks mnoho dlužen? Kterýž řekl: Sto korců pšenice. A dí mu: Vezmi rejistra svá, a napiš osmdesát."],[8,"pochválil ten pán vládaře toho nepravého, že opatrně udělal. Protože synové tohoto světa opatrnější jsou, než synové světla v svých věcech."],[9,"jáť říkám vám: Čiňte sobě přátely z mamony nepravosti, aby, když byste zhynuli, přijali vás do oněch věčných stanů."],[10,"Kdo je věrný v mále, i ve mnoze věrný je. A kdož v mále je nepravý, i ve mnozeť nepravý je."],[11,"Poněvadž tedy v mamoně nepravé věrni jste nebyli, spravedlivé kdo vám svěří?"],[12,"když jste v cizím věrni nebyli, což vašeho je, kdo vám dá?"],[13,"Žádný čeledín nemůž dvěma pánům sloužiti. Nebť zajisté jednoho nenáviděti bude, a druhého milovati, aneb jednoho přídržeti se bude, a druhým pohrdne. Nemůžte Bohu sloužiti a mamoně."]]},{"title":"Zákon a Boží království","range":"Lk 16,14–18","thoughts":[],"verses":[[14,"Slyšeli pak toto všechno i farizeové, kteříž byli lakomí, a posmívali se mu."],[15,"dí jim: Vy jste, ješto se sami spravedliví činíte před lidmi, ale Bůhť zná srdce vaše; nebo což je u lidí vysokého, ohavnost je před Bohem."],[16,"Zákon a proroci až do Jana, a od té chvíle království Boží zvěstuje se, a každý se do něj násilně tiskne."],[17,"Snázeť je zajisté nebi i zemi pominouti, nežli v zákoně jednomu tytlíku zahynouti."],[18,"Každý, kdož propustí manželku svou, a jinou pojímá, cizoloží; a kdož propuštěnou od muže pojímá, cizoloží."]]},{"title":"Boháč a Lazar","range":"Lk 16,19–31","thoughts":[],"verses":[[19,"Byl pak člověk jeden bohatý, a obláčel se v šarlat a v kment, a hodoval na každý den stkvostně."],[20,"byl jeden žebrák, jménem Lazar,kterýž ležel u vrat jeho vředovitý,"],[21,"Žádaje nasycen býti těmi drobty, kteříž padali z stolu bohatce. Ale i psi přicházejíce, lízali vředy jeho."],[22,"stalo se, že ten žebrák umřel, a nesen je od andělů do lůna Abrahamova. Umřel pak i bohatec, a pohřben je."],[23,"v pekle pozdvih očí svých, v mukách když byl, uviděl Abrahama zdaleka, a Lazara v lůnu jeho."],[24,"zvolav bohatec, řekl: Otče Abrahame, smiluj se nade mnou, a pošli Lazara, ať omočí konec prstu svého v vodě, a svlaží jazyk můj; nebo se mučím v tomto plameni."],[25,"řekl Abraham: Synu, rozpomeň se, žes ty vzal dobré věci své v životě svém, a Lazar též zlé. Nyní pak tento se těší, ale ty se mučíš."],[26,"nad to nade všechno mezi námi a vámi propast veliká utvrzena je, aby ti, kteříž chtí odsud k vám jíti, nemohli, ani od onud k nám přejíti."],[27,"řekl: Ale prosím tebe, otče, abys ho poslal do domu otce mého."],[28,"Protožeť mám pět bratrů. Ať jim svědčí, aby i oni nepřišli do tohoto místa muk."],[29,"řekl mu Abraham: Majíť Mojžíše a proroky, nechť jich poslouchají."],[30,"on řekl: Nic, otče Abrahame, ale kdyby kdo z mrtvých šel s nim, budou pokání činiti."],[31,"řekl mu: Poněvadž Mojžíše a proroků neposlouchají, aniž byť kdo z mrtvých vstal, uvěří mu."]]}];

LUKE_SECTIONS["17"] = [{"title":"Pohoršení, odpuštění a víra","range":"Lk 17,1–10","thoughts":[],"verses":[[1,"řekl učedníkům: Není možné, aby nepřišla pohoršení, ale běda, skrze kohož přicházejí."],[2,"Lépe by mu bylo, aby žernov osličí vložen byl na hrdlo jeho, a uvržen byl do moře, než by pohoršil jednoho z těchto maličkých."],[3,"Šetřte se. Zhřešil-li by pak proti tobě bratr tvůj, potresci ho, a bude-liť toho želeti, odpusť mu."],[4,"byť pak sedmkrát za den zhřešil proti tobě, a sedmkrát za den obrátil se k tobě, řka: Žel mi toho, odpusť mu."],[5,"řekli apoštolé Pánu: Přispoř nám víry."],[6,"dí Pán: Kdybyste měli víru jako zrno horčičné, řekli byste této moruši: Vykořeň se, a přesaď se do moře, a uposlechla by vás."],[7,"Kdo pak je z vás, měl služebníka, ješto oře aneb pase, aby mu, když by se s pole navrátil, hned řekl: Poď a sedni za stůl?"],[8,"Anobrž zda nedí mu: Připrav, ať povečeřím, a opáše se, služ mi, až se najím a napím, a potom i ty jez a pí?"],[9,"Zdali děkuje služebníku tomu, že udělal to, což mu bylo rozkázáno? Nezdá mi se."],[10,"Tak i vy, když uděláte všechno, což vám přikázáno, rcete: Služebníci neužiteční jsme. Což jsme povinni byli udělat, učinili jsme."]]},{"title":"Uzdravení deseti malomocných","range":"Lk 17,11–19","thoughts":[],"verses":[[11,"stalo se, když se bral do Jeruzaléma, že šel skrze Samaří a Galilei."],[12,"když vcházel do nějakého městečka, potkalo se s ním deset mužů malomocných, kteříž stáli zdaleka."],[13,"pozdvihše hlasu, řekli: Ježíši přikazateli, smiluj se nad námi."],[14,"Kteréžto on když uviděl, řekl jim: Jdouce, ukažte se kněžím. A stalo se, když šli, že očištěni jsou."],[15,"Jeden pak z nich když uviděl, že je uzdraven, navrátil se, s velikým hlasem velebě Boha."],[16,"padl na tvář k nohám jeho, řeklky čině mu. A ten byl Samaritán."],[17,"odpověděv Ježíš, řekl: Zdaliž jich deset není očištěno? A kdež jich devět?"],[18,"Nenalezli se, aby vrátíce se, chválu Bohu vzdali, jediné cizozemec tento?"],[19,"řekl mu: Vstana jdi, víra tvá tě uzdravila."]]},{"title":"Příchod Božího království","range":"Lk 17,20–37","thoughts":[],"verses":[[20,"Byv pak otázán od farizeů, kdy přijde království Boží, odpověděl jim, a řekl: Nepřijdeť království Boží s šetřením."],[21,"Aniž řeknou: Hle, tuto, aneb aj, tamto. Protože aj, království Boží jestiť mezi vámi."],[22,"řekl učedníkům: Přijdou dnové, že budete žádati viděti v jeden den Syna člověka, ale neuzříte."],[23,"dějíť vám: Hle, zde, aneb hle, tamto. Ale nechoďte, aniž následujte."],[24,"Protože jakož blesk osvěcující se z jedné krajiny, kteráž pod nebem je, až do druhé, kteráž též pod nebem je, svítí, tak bude i Syn člověka ve dni svém."],[25,"Ale nejprvé musí mnoho trpěti, a zavržen býti od národu tohoto."],[26,"jakož se dálo za dnů Noé, tak bude i za dnů Syna člověka."],[27,"Jedli, pili, ženili se, vdávaly se až do toho dne, v kterémž Noé všel do korábu; i přišla potopa, a zahladila všecky."],[28,"též podobně, jakž se dálo ve dnech Lotových: Jedli, pili, kupovali, prodávali, štěpovali, stavěli."],[29,"Ale dne toho, když vyšel Lot z Sodomy, dštil ohněm a sirou s nebe, a zahladil všecky."],[30,"Takť nápodobně bude v ten den, když se Syn člověka zjeví."],[31,"V ten den kdo by byl na střeše, a nádobí jeho v domu, nesstupuj, aby je pobral; a kdo na poli, též nevracuj se zase."],[32,"Pomněte na Lotovu ženu."],[33,"Kdož by koli hledal duši svou zachovati, ztratíť ji; a kdož by ji koli ztratil, obživíť ji."],[34,"Pravímť vám: V tu noc budou dva na loži jednom; jeden bude vzat, a druhý opuštěn."],[35,"Dvě budou mleti spolu; jedna bude vzata, a druhá opuštěna."],[36,"Dva budou na poli; jeden bude vzat, a druhý opuštěn."],[37,"odpověděvše, řekli mu: Kde, Pane? On pak řekl jim: Kdežť bude tělo, tamť se shromáždí i orlice."]]}];
LUKE_SECTIONS["18"] = [{"title":"Vytrvalá vdova","range":"Lk 18,1–8","thoughts":[],"verses":[[1,"Pověděl jim také i podobenství, jak by potřebí bylo vždycky se modliti a neoblevovati,"],[2,"Řka: Byl jeden soudce v městě jednom, kterýž se Boha nebál, a člověka nestyděl."],[3,"Byla pak vdova v témž městě. A přišla k němu, řkuci: Pomsti mne nad protivníkem mým."],[4,"On pak dlouho nechtěl. Ale potom řekl sám v sobě: Ač se Boha nebojím, ani člověka nestydím,"],[5,"Však že mi pokoje nedá tato vdova, pomstím jí, aby naposledy přijduci, neuhaněla mne."],[6,"dí Pán: Slyšte, co praví ten soudce nepravý."],[7,"což by pak Bůh nepomstil vyvolených svých, volajících k němu dnem i nocí, ačkoli i prodlévá jim?"],[8,"Pravímť vám, žeť jich brzo pomstí. Ale když přijde Syn člověka, zdaž nalezne víru na zemi?"]]},{"title":"Farizeus a celník","range":"Lk 18,9–14","thoughts":[],"verses":[[9,"řekl také proti některým, kteříž v sebe doufali, že by spravedliví byli, jiných za nic nevážíce, podobenství toto:"],[10,"Dva muži vstupovali do chrámu, aby se modlili, jeden farizeus, a druhý celník."],[11,"Farizeus stoje, takto se sám v sobě modlil: Bože, děkuji tobě, že nejsem jako jiní lidé, dráči, nespravedliví, cizoložníci, aneb jako i tento celník."],[12,"Postím se dvakrát do téhodne, desátky dávám ze všech věcí, kterýmiž vládnu."],[13,"Publikán pak zdaleka stoje, nechtěl ani očí k nebi pozdvihnouti. Ale bil se v prsy své, řka: Bože, buď milostiv mně hříšnému."],[14,"Pravímť vám: Odšel tento, ospravedlněn když byl, do domu svého, a ne onen. Protože každý, kdož se povyšuje, bude ponížen; a kdož se ponižuje, bude povýšen."]]},{"title":"Ježíš a děti","range":"Lk 18,15–17","thoughts":[],"verses":[[15,"Přinášeli také k němu i nemluvňátka, aby se jich dotýkal. To když vidělše učedlníci, přimlouvali jim."],[16,"Ale Ježíš svolav je, řekl: Nechte řekltek, ať jdou ke mně, a nebraňte jim, nebo takovýchť je království Boží."],[17,"Amen, říkám vám: Kdož by koli nepřijal království Božího jako řekltě, nevejdeť nikoli do něj."]]},{"title":"Bohatý přední muž","range":"Lk 18,18–30","thoughts":[],"verses":[[18,"otázalo se ho jedno kníže, řka: Mistře dobrý, co čině, život věčný obdržím?"],[19,"řekl mu Ježíš: Co mne nazýváš dobrým? Žádný není dobrý, než jediný, totiž Bůh."],[20,"Umíš přikázaní: Nezcizoložíš, nezabiješ, nepokradeš, nepromluvíš křivého svědectví, cti otce svého i matku svou."],[21,"On pak řekl: Toho všeho ostříhal jsem od své mladosti."],[22,"Ale když uslyšel to Ježíš, řekl mu: Ještěť se jednoho nedostává. Všecko, což máš, prodej, a rozdej chudým, a budeš míti poklad v nebi, a poď, následuj mne."],[23,"On pak uslyšav to, zarmoutil se; byl zajisté bohatý velmi."],[24,"když viděl ho Ježíš zarmouceného, řekl: Hle, jak nesnadně ti, kdož statky mají, do království Božího vejdou!"],[25,"Snáze je zajisté velbloudu skrze jehelnou řeklrku projíti, nežli bohatému vjíti do království Božího."],[26,"řekli ti, kteříž to slyšeli: A kdož může spasen býti?"],[27,"on dí: Což je nemožného u lidí, možné je u Boha."],[28,"řekl Petr: Hle, my opustili jsme všechno, a šli jsme za tebou."],[29,"On pak řekl jim: Amen, říkám vám, že není žádného, kterýž by opustil dům, neb rodiče, neb bratří, neb manželku, neb řekltky, pro království Boží,"],[30,"Aby nevzal v tomto času mnohem více, v budoucím pak věku života věčného."]]},{"title":"Třetí předpověď utrpení","range":"Lk 18,31–34","thoughts":[],"verses":[[31,"pojav dvanácte, řekl jim: Hle, vstupujeme do Jeruzaléma, a naplníť se všechno Synu člověka to, což psáno je skrze proroky."],[32,"Protože vydán bude pohanům, a bude posmíván, a zlehčen, i uplván."],[33,"ubičujíce, zamordují ho, ale třetího dne z mrtvých vstane."],[34,"Oni pak tomu nic nerozuměli, a bylo slovo to skryto před nimi, aniž věděli, co se pravilo."]]},{"title":"Uzdravení slepého u Jericha","range":"Lk 18,35–43","thoughts":[],"verses":[[35,"stalo se, když se přibližovali k Jericho, slepý jeden seděl podlé cesty, žebře."],[36,"slyšev zástup pomíhoící, otázal se, co by to bylo."],[37,"oznámili mu, že Ježíš Nazaretský tudy jde."],[38,"zvolal, řka: Ježíši, synu Davidův, smiluj se nade mnou."],[39,"ti, kteříž napřed šli, přimlouvali mu, aby mlčal. Ale on mnohem více volal: Synu Davidův, smiluj se nade mnou."],[40,"zastaviv se Ježíš, rozkázal ho k sobě přivésti. A když se přibližoval, otázal se ho,"],[41,"Řka: Co chceš, ať udělám? On pak dí: Pane, ať vidím."],[42,"Ježíš řekl mu: Prohlédni. Víra tvá tě uzdravila."],[43,"i hned prohlédl, a šel za ním, velebě Boha. A celý lid když viděl to, vzdal chválu Bohu."]]}];

LUKE_SECTIONS["19"] = [{"title":"Zacheus","range":"Lk 19,1–10","thoughts":[],"verses":[[1,"všel, bral se přes Jericho."],[2,"aj, muž, jménem Zacheus, a ten byl hejtman nad celnými, a byl bohatý."],[3,"žádostiv byl viděti Ježíše, kdo by byl; a nemohl pro zástup, nebo postavy malé byl."],[4,"předběh napřed, vstoupil na strom planého fíku, aby ho viděl; nebo tudy měl jíti."],[5,"když přišel k tomu místu, pohleděv zhůru Ježíš, uviděl ho, i řekl mu: Zachee, spěšně sstup dolů, nebo dnes v domu tvém musím zůstati."],[6,"sstoupil rychle, a přijal ho radostně."],[7,"když vidělše to všichni, reptali, řkouce: K člověku hříšnému se obrátil."],[8,"Stoje pak Zacheus, řekl Pánu: Hle, polovici statku svého, Pane, dávám chudým, a oklamal-li jsem v čem koho, navracuji to čtvernásob."],[9,"dí mu Ježíš: Dnes spasení stalo se domu tomuto, proto že i on je syn Abrahamův."],[10,"Protože přišel Syn člověka, aby hledal a spasil, což bylo zahynulo."]]},{"title":"Podobenství o hřivnách","range":"Lk 19,11–27","thoughts":[],"verses":[[11,"Toho když oni poslouchali, promluvil k nim dále podobenství, proto že byl blízko od Jeruzaléma, a že se oni domnívali, že by se hned mělo zjeviti království Boží."],[12,"řekl: Člověk jeden rodu znamenitého odšel do daleké krajiny, aby přijal království, a zase se navrátil."],[13,"povolav desíti služebníků svých, dal jim deset hřiven, a řekl jim: Kupčtež, dokudž nepřijdu."],[14,"Měšťané pak jeho nenáviděli ho, a poslali poselství za ním, řkouce: Nechcemeť, aby tento kraloval nad námi."],[15,"stalo se, když se navrátil, přijav království, že rozkázal zavolati těch svých služebníků, kterýmž byl dal peníze, aby zvěděl, jak kdo mnoho získal."],[16,"přišel první, řka: Pane, hřivna tvá deset hřiven získala."],[17,"řekl mu: To dobře, služebníče dobrý. Že jsi nad málem byl věrný, mějž moc nad desíti městy."],[18,"druhý přišel, řka: Pane, hřivna tvá získala pět hřiven."],[19,"tomu řekl: A ty budiž nad pěti městy."],[20,"jiný přišel, řka: Pane, aj, teď hřivna tvá, kterouž jsem měl složenou v šátku."],[21,"Protože jsem se bál tebe, ješto jsi člověk přísný; béřeš, čeho jsi nepoložil, a žneš, čeho jsi nerozsíval."],[22,"řekl mu: Z úst tvých soudím tebe, služebníče zlý. Věděl jsi, že jsem já člověk přísný, bera, což jsem nepoložil, a žna, čehož jsem nerozsíval."],[23,"proč jsi tedy nedal peněz mých na stůl, a já přijda, byl bych je vzal i s užitky."],[24,"řekl těm, kteříž tu stáli: Vezměte od něj tu hřivnu, a dejte tomu, kterýž má deset hřiven."],[25,"řekli mu: Pane, máť deset hřiven."],[26,"Jistě říkám vám: Že každému, kdož má, bude dáno, ale od toho, kterýž nemá, i to, což má, bude odjato."],[27,"Ty pak nepřátely mé, kteříž nechtěli, abych nad nimi kraloval, přiveďte sem, a zmordujte přede mnou."]]},{"title":"Vjezd do Jeruzaléma","range":"Lk 19,28–40","thoughts":[],"verses":[[28,"To pověděv, šel napřed, vstupuje k Jeruzalému."],[29,"stalo se, když se přiblížil k Betfagi a k Betany, k hoře, kteráž slove Olivetská, poslal dva učedníky své,"],[30,"Řka: Jděte do městečka, kteréž proti vám je. Do kteréhož vejdouce, naleznete oslátko přivázané, na němž nikdy žádný z lidí neseděl. Odvěžtež je, a přiveďte ke mně."],[31,"optal-liť by se vás kdo, proč odvazujete, tak řeklte mu: Proto že Pán ho potřebuje."],[32,"odšelše ti, kteříž byli posláni, nalezli, jakž jim byl pověděl."],[33,"když odvazovali to oslátko, řekli páni jeho k nim: Proč odvazujete oslátko?"],[34,"oni řekli: Pán ho potřebuje."],[35,"přivedli je k Ježíšovi, a vloživše oděvy svá na to oslátko, vsadili na ně Ježíše."],[36,"když on jel, stlali oděvy svá na cestě."],[37,"Když se pak již přibližoval k místu tomu, kudyž scházejí s hory Olivetské, počalo všechno množství učedníků radostně chváliti Boha hlasem velikým ze všech divů, kteréž byli viděli,"],[38,"Řkouce: Požehnaný král, kterýž se béře ve jménu Páně. Pokoj na nebi, a sláva na výsostech."],[39,"Ale někteří z farizeů, kteříž tu byli v zástupu, řekli mu: Mistře, potresci učedníků svých."],[40,"odpověděv, řekl jim: Pravímť vám: Budou-li tito mlčeti, kamení hned bude volati."]]},{"title":"Ježíš pláče nad Jeruzalémem","range":"Lk 19,41–44","thoughts":[],"verses":[[41,"když se přiblížil, když uviděl město, plakal nad ním,"],[42,"Řka: Ó kdybys poznalo i ty, a to aspoň v takový tento den tvůj, které by věci ku pokoji tobě byly, ale skrytoť je to nyní před očima tvýma."],[43,"Protože přijdou na tě dnové, obklíčí tě nepřátelé tvoji valem, a oblehnou tebe, a ssouží tě se všech stran."],[44,"s zemí srovnají tě, i syny tvé v tobě, a nenechajíť v tobě kamene na kameni, proto že jsi nepoznalo času navštívení svého."]]},{"title":"Vyčištění chrámu","range":"Lk 19,45–48","thoughts":[],"verses":[[45,"všel do chrámu, počal vymítati prodavače a kupce z něj,"],[46,"Řka jim: Psáno je: Dům můj dům modlitby je, vy jste ho pak učinili peleší lotrovskou."],[47,"učil na každý den v chrámě. Přední pak kněží {biskupové} a zákonníci i přední v lidu hledali ho zahladiti."],[48,"Ale nenalezli, co by učinili. Protože celý lid ho sobě liboval, poslouchaje ho."]]}];

LUKE_SECTIONS["20"] = [{"title":"Otázka Ježíšovy autority","range":"Lk 20,1–8","thoughts":[],"verses":[[1,"stalo se těch dnů v jeden den, když on učil lid v chrámě, a kázal evangelium, že přišli k tomu přední kněží {biskupové} a zákonníci s staršími."],[2,"řekli mu: pověz nám, jakou mocí tyto věci činíš, aneb kdo je ten, kterýž tobě tuto moc dal?"],[3,"odpověděv, řekl jim: Otížiť se i já vás na jednu věc; protož pověztež mi:"],[4,"Křest Janův s nebe-li byl, čili z lidí?"],[5,"Oni pak uvažovali to mezi sebou, řkouce: Jestliže bychom řekli: S nebe, díť: Pročež jste tedy neuvěřili mu?"],[6,"Pakli řeklme: Z lidí, lid celý ukamenuje nás; nebo cele tak drží, že Jan je prorok."],[7,"odpověděli: Že nevědí, odkud byl."],[8,"řekl jim Ježíš: Aniž já vám povím, jakou mocí toto činím."]]},{"title":"Podobenství o zlých vinařích","range":"Lk 20,9–19","thoughts":[],"verses":[[9,"počal lidu praviti podobenství toto: Člověk jeden štípil vinici, a pronajal ji vinařům, a sám odšel přes pole na dlouhé časy."],[10,"v čas slušný poslal k těm vinařům služebníka, aby užitek z vinice dali mu. Ti pak vinaři zmrskavše ho, pustili prázdného."],[11,"poslal druhého služebníka. Oni pak i toho zmrskavše a zohavivše, pustili prázdného."],[12,"poslal třetího. Ale oni i toho zranivše, vystrčili ven."],[13,"řekl pán té vinice: Co udělám? Pošli svého milého syna. Snad když toho uzří, ustýdnou se."],[14,"Ale vinaři když uvidělše ho, rozmlouvali mezi sebou, řkouce: Tentoť je dědic; pojďte, zabíme ho, aby naše bylo to dědictví."],[15,"vystrčivše ho ven z vinice, zamordovali. Což tedy učiní jim pán té vinice?"],[16,"Přijde a vyhladí vinaře ty, a dá vinici jiným. To uslyšavše, řekli: Odstup to."],[17,"Ale on pohleděv na ně, řekl: Co je pak to, což napsáno je: Kámen, kterýmž pohrdli stavitelé, ten učiněn je v hlavu úhelní?"],[18,"Každý, kdož padne na ten kámen, rozrazí se; a na kohož by on upadl, potřeť ho."],[19,"hledali přední kněží {biskupové} a zákonníci, jak by naň vztáhli ruce v tu hodinu, ale báli se lidu. Protože porozuměli, že by na ně mluvil podobenství to."]]},{"title":"Daň císaři","range":"Lk 20,20–26","thoughts":[],"verses":[[20,"střehnouce ho, poslali špehéře, kteříž by se spravedlivými činili, aby ho polapili v řeči, a potom ho vydali vrchnosti a v moc hejtmanu."],[21,"otázali se ho, řkouce: Mistře, víme, že právě mluvíš a učíš, a nepřijímáš osoby, ale v pravdě cestě Boží učíš."],[22,"Sluší-li nám daň dávati císaři, čili nic?"],[23,"Ale porozuměv chytrosti jejich, dí jim: Co mne pokoušíte?"],[24,"Ukažte mi peníz. Čí má obraz a nápis? A odpověděvše, řekli: Císařův."],[25,"On pak řekl jim: Dejtež tedy, co je císařova, císaři, a co je Božího, Bohu."],[26,"nemohli ho za slovo popadnouti před lidem, a divíce se odpovědi jeho, umlkli."]]},{"title":"Otázka vzkříšení","range":"Lk 20,27–40","thoughts":[],"verses":[[27,"Přistoupivše pak někteří z saduceů, (kteříž odpírají býti vzkříšení), otázali se ho,"],[28,"Řkouce: Mistře, Mojžíš napsal nám: Kdyby bratr něčí umřel, měl manželku, a umřel by bez dětí, aby ji pojal bratr jeho za manželku, a vzbudil símě bratru svému."],[29,"bylo sedm bratří, a první pojav ženu, umřel bez dětí."],[30,"pojal druhý tu ženu, a umřel i ten bez dětí."],[31,"třetí pojal ji, též i všech těch sedm, a nezůstavivše dětí, zemřeli."],[32,"Nejposléze po všech umřela i ta žena."],[33,"Protož při vzkříšení, kterého z nich bude ta žena, poněvadž sedm jich mělo ji za manželku?"],[34,"odpovídaje, řekl jim Ježíš: Synové tohoto věku žení se a vdávají."],[35,"Ale ti, kteříž hodni jmíni budou dosáhnouti onoho věku a vzkříšení z mrtvých, ani se ženiti nebudou ani vdávati."],[36,"Protože ani umírati více nebudou moci, andělům zajisté rovni budou. A jsou synové Boží, poněvadž jsou synové vzkříšení."],[37,"že mrtví vstanou z mrtvých, i Mojžíš ukázal při onom kři, když nazývá Pána Bohem Abrahamovým, a Bohem Izákovým, a Bohem Jákobovým."],[38,"Bůhť pak není mrtvých, ale živých, nebo všichni jsou mu živi."],[39,"odpověděvše někteří z zákonníků, řekli: Mistře, dobře jsi pověděl."],[40,"nesměli se jeho na nic více tázati."]]},{"title":"Čí syn je Mesiáš","range":"Lk 20,41–44","thoughts":[],"verses":[[41,"Řekl pak jim: Kterak praví Krista býti synem Davidovým?"],[42,"sám David praví v knize žalmů: Řekl Pán Pánu mému: Seď na pravici mé,"],[43,"Ažť položím nepřátely tvé v podnož noh tvých?"],[44,"Poněvadž David ho Pánem nazývá, i jakž syn jeho je?"]]},{"title":"Varování před zákoníky","range":"Lk 20,45–47","thoughts":[],"verses":[[45,"řekl učedníkům svým přede vším lidem:"],[46,"Varujte se zákonníků, kteříž rádi chodí v krásném rouše, a milují pozdravování na trzích a přední stolice v školách, a první místo na večeřích."],[47,"Kteříž zžírají domy vdovské pod zámyslem dlouhé modlitby. Tiť vezmou těžší odsouzení."]]}];

LUKE_SECTIONS["21"] = [{"title":"Dar chudé vdovy","range":"Lk 21,1–4","thoughts":[],"verses":[[1,"pohleděv, uviděl bohaté, kteříž metali dary své do pokladnice."],[2,"Uzřel pak i jednu vdovu chudičkou, ana uvrhla tam dva šarty."],[3,"řekl: V pravdě říkám vám, že vdova tato chudá více než všichni uvrhla."],[4,"Protože všichni tito z toho, což jim zbývalo, dali dary Bohu, tato pak z své chudoby všecku živnost svou, kterouž měla, uvrhla."]]},{"title":"Proroctví o zničení chrámu","range":"Lk 21,5–9","thoughts":[],"verses":[[5,"když někteří říkali o chrámu, jak by kamením pěkným i okrasami ozdoben byl, řekl:"],[6,"Nač se to řeklváte? Přijdouť dnové, v nichž nebude zůstaven kámen na kameni, kterýž by nebyl zbořen."],[7,"otázali se ho, řkouce: Mistře, kdy to bude? A které znamení, když se to bude míti státi?"],[8,"On pak řekl: Vizte, abyste nebyli svedeni. Protože mnozí přijdou ve jménu mém, řkouce: Já jsem, a čas se blíží. Protož nepostupujte po nich."],[9,"Když pak uslyšíte o válkách a různicech, nestrachujte se; neboť musí to prvé býti, ale ne i hned konec."]]},{"title":"Války a pronásledování","range":"Lk 21,10–19","thoughts":[],"verses":[[10,"Tehdy řekl jim: Povstaneť národ proti národu, a království proti království."],[11,"země třesení veliká budou po místech, a hladové, a morové, hrůzy i zázrakové s nebe velicí."],[12,"Ale před tím přede vším vztáhnou ruce své na vás, a protiviti se budou, vydávajíce vás do škol a žalářů, vodíce k králům a k vládařům pro jméno mé."],[13,"toť se vám řeklti bude na svědectví."],[14,"Protož složtež to v srdcích svých, abyste se nestarali, jak byste odpovídati měli."],[15,"Jáť zajisté dám vám ústa a moudrost, kteréž nebudou moci odolati, ani proti ní ostáti všichni protivníci vaši."],[16,"Budete pak zrazováni i od rodičů a od bratří, od příbuzných i od přátel, a zmordují některé z vás."],[17,"budete v nenávisti u všech pro jméno mé."],[18,"Ale ani vlas s hlavy vaší nikoli nezahyne."],[19,"V trpělivosti své vládněte dušemi svými."]]},{"title":"Zkáza Jeruzaléma","range":"Lk 21,20–24","thoughts":[],"verses":[[20,"Když pak uzříte obležený od vojska Jeruzalém, tehdy vězte, žeť se přiblížilo zkažení jeho."],[21,"Tehdy ti, kdož jsou v Judstvu, utíkejte k horám, a kdo u prostřed něj, vyjděte, a kteří v končinách, nevcházejte do něj."],[22,"Protožeť budou dnové pomsty, aby se naplnilo všechno, což psáno je."],[23,"Ale běda těhotným a těm, kteréž kojí v těch dnech. Protožeť bude dav veliký v této zemi, a hněv nad lidem tímto."],[24,"padati budou ostrostí meče, a zjímaní vedeni budou mezi všecky národy, a Jeruzalém tlačen bude od pohanů, dokudž se nenaplní časové pohanů."]]},{"title":"Příchod Syna člověka","range":"Lk 21,25–28","thoughts":[],"verses":[[25,"budouť znamení na slunci a na měsíci i na hvězdách, a na zemi ssoužení národů, nevědoucích se kam řeklti, když zvuk vydá moře a vlnobití,"],[26,"Tak že zmrtvějí lidé pro strach a pro očekávání těch věcí, kteréž přijdou na celý svět. Protože moci nebeské pohybovati se budou."],[27,"tehdyť uzří Syna člověka, an se béře v oblace s mocí a slavou velikou."],[28,"když se toto počne řeklti, pohleďtež a pozdvihnětež hlav svých, proto že se přibližuje vykoupení vaše."]]},{"title":"Podobenství o fíkovníku","range":"Lk 21,29–33","thoughts":[],"verses":[[29,"pověděl jim podobenství: Patřte na fíkový strom i na všechna stromoví."],[30,"Když se již pučí, vidouce to, sami to znáte, že blízko je již léto."],[31,"Takž i vy, když uzříte, ano se tyto věci dějí, vězte, že blízko je království Boží."],[32,"Amen, říkám vám, že nepomine věk tento, až se všechno stane."],[33,"Nebe a země pominou, ale slova má nepominou."]]},{"title":"Bděte","range":"Lk 21,34–38","thoughts":[],"verses":[[34,"Pilně se pak varujte, aby snad nebyla obtížená srdce vaše obžerstvím a opilstvím a starostim o tento život, a v náhle přikvačil by vás ten den."],[35,"Protože jako osídlo přijde na všecky, kteříž přebývají na tváři vší země."],[36,"Protož bděte, všelikého času modléce se, abyste hodni byli ujíti všech těch věcí, kteréž se budou řeklti, a postaviti se před Synem člověka."],[37,"býval ve dne v chrámě, uče, ale v noci vycházeje, přebýval na hoře, kteráž slove Olivetská."],[38,"celý lid na úsvitě přicházel k němu do chrámu, aby ho poslouchal."]]}];

LUKE_SECTIONS["22"] = [{"title":"Spiknutí a Jidášova zrada","range":"Lk 22,1–6","thoughts":[],"verses":[[1,"Přibližoval se pak svátek přesnic, kterýž slove velikanoc."],[2,"hledali přední kněží {biskupové} a zákonníci, jak by ho vyhladili; nebo obávali se lidu."],[3,"vstoupil satan do Jidáše, přijmím Aškariotského, kterýž byl z počtu dvanácti."],[4,"on odšel, mluvil s předními kněžími {biskupy}, a s úředníky, jak by ho jim zradil."],[5,"zradovali se, a smluvili s ním, že mu chtí peníze dáti."],[6,"slíbil, a hledal příhodného času, aby ho jim zradil bez zástupu."]]},{"title":"Příprava velikonoční večeře","range":"Lk 22,7–13","thoughts":[],"verses":[[7,"přišel den přesnic, v kterémž zabit měl býti beránek."],[8,"poslal Petra a Jana, řka: Jdouce, připravte nám beránka, abychom jedli."],[9,"oni řekli mu: Kde chceš, ať připravíme?"],[10,"On pak řekl jim: Hle, když vcházeti budete do města, potkáť vás člověk, dčbán vody nesa. Jdětež za ním do domu, do kteréhož vejde."],[11,"řeklte hospodáři toho domu: Vzkazuje tobě Mistr: Kde je síň, kdež budu jísti beránka s učedníky svými?"],[12,"onť vám ukáže večeřadlo veliké podlážené. Tam připravte."],[13,"odšelše, nalezli, jakž jim pověděl, a připravili beránka."]]},{"title":"Poslední večeře","range":"Lk 22,14–23","thoughts":[],"verses":[[14,"když přišel čas, posadil se za stůl, a dvanácte apoštolů s ním."],[15,"řekl jim: Žádostí žádal jsem tohoto beránka jísti s vámi, prvé než bych trpěl."],[16,"Protože říkámť vám, žeť ho již více nebudu jísti, ažť se naplní v království Božím."],[17,"vzav kalich, a řeklky činiv, řekl: Vezměte ho a dělte mezi sebou."],[18,"Protože říkám vám, žeť nebudu píti z plodu vinného kořene, ažť království Boží přijde."],[19,"vzav chléb, a řeklky činiv, lámal a dal jim, řka: To je tělo mé, kteréž se za vás dává. To čiňte na mou památku."],[20,"Takž i kalich, když bylo po večeři, řka: Tento kalich je ta nová smlouva v mé krvi, kteráž se za vás vylévá."],[21,"Ale aj, ruka zrádce mého se mnou za stolem."],[22,"Syn zajisté člověka jde, tak jakž je uloženo, ale běda člověku tomu, kterýž ho zrazuje."],[23,"oni počali vyhledávati mezi sebou, kdo by z nich byl, kterýž by to měl udělat."]]},{"title":"Kdo je největší","range":"Lk 22,24–30","thoughts":[],"verses":[[24,"Stal se pak i svár mezi nimi, kdo by z nich zdál se býti největší."],[25,"On pak řekl jim: Králové národů panují nad nimi, a kteříž moc mají nad nimi, dobrodincové slovou."],[26,"Ale vy ne tak. Nýbrž kdož největší je mezi vámi, budiž jako nejmenší, a kdož vůdce je, jako sloužící."],[27,"Protože kdo větší, ten-li, kterýž sedí, čili ten, kterýž slouží? Zdali ne ten, kterýž sedí? Ale já mezi vámi jsem jako ten, kterýž slouží."],[28,"Vy pak jste ti, kteříž jste v mých pokušeních se mnou zůstali."],[29,"jáť vám způsobuji, jakož mi způsobil Otec můj, království,"],[30,"Abyste jedli a pili za stolem mým v království mém, a seděli na stolicích, soudíce dvanáctero pokolení Izraelské."]]},{"title":"Ježíš předpovídá Petrovo zapření","range":"Lk 22,31–38","thoughts":[],"verses":[[31,"řekl Pán: Šimone, Šimone, aj, satan vyprosil, aby vás tříbil jako pšenici."],[32,"Ale jáť jsem prosil za tebe, aby nezhynula víra tvá. A ty někdy obrátě se, potvrzuj bratří svých."],[33,"on řekl mu: Pane, s tebou hotov jsem i do žaláře i na smrt jíti."],[34,"On pak dí: Pravím tobě, Petře, nezazpíváť dnes kohout, až prvé třikrát zapříš, že neznáš mne."],[35,"řekl jim: Když jsem vás posílal bez pytlíka, a bez mošny, a bez obuvi, zda jste v čem nedostatek měli? A oni řekli: V ničemž."],[36,"dí jim: Ale nyní, kdo má pytlík, vezmi a též i mošnu; a kdož meče nemá, prodej sukni svou, a kup sobě."],[37,"Protože říkám vám, že se ještě to písmo naplniti musí na mně: A s nešlechetnými počten je. Protože ty věci, kteréž svědčí o mně, konec berou."],[38,"Oni pak řekli: Pane, aj, dva meče teď. A on řekl jim: Dostiť je."]]},{"title":"Ježíš na Olivové hoře","range":"Lk 22,39–46","thoughts":[],"verses":[[39,"vyšel, šel podlé obyčeje svého na horu Olivovou, a šli za ním i učedlníci jeho."],[40,"když přišel na místo, řekl jim: Modlte se, abyste nevešli v pokušení."],[41,"sám vzdáliv se od nich, jako by mohl kamenem dohoditi, a poklek na kolena, modlil se,"],[42,"Řka: Otče, chceš-li, přenes kalich tento ode mne, ale však ne má vůle, ale tvá staň se."],[43,"ukázal se mu anděl s nebe, posiluje ho."],[44,"když byl v boji, horlivěji se modlil. A učiněn je pot jeho jako krůpě krve tekoucí na zemi."],[45,"vstal od modlitby, a přišel k učedníkům, nalezl je, ani spí zámutkem."],[46,"řekl jim: Co spíte? Vstaňte a modlte se, abyste nevešli v pokušení."]]},{"title":"Ježíšovo zatčení","range":"Lk 22,47–53","thoughts":[],"verses":[[47,"když on ještě mluvil, aj, zástup, a ten, kterýž sloul Jidáš, jeden ze dvanácti, šel napřed, a přiblížil se k Ježíšovi, aby ho políbil."],[48,"Ježíš pak řekl mu: Jidáši, políbením Syna člověka zrazuješ."],[49,"vidouce ti, kteříž při něm byli, k čemu se chýlí, řekli mu: Pane, budeme-liž bíti mečem?"],[50,"udeřil jeden z nich služebníka nejvyššího kněze {biskupova}, a uťal ucho jeho pravé."],[51,"Ježíš odpověděv, řekl: Nechtež až potud. A dotek se ucha jeho, uzdravil ho."],[52,"dí Ježíš těm, kteříž přišli na něj, předním kněžím {biskupům} a úředníkům chrámu a starším: Jako na lotra vyšli jste s meči a s kyjmi."],[53,"Ješto na každý den býval jsem s vámi v chrámě, a nevztáhli jste rukou na mne. Ale totoť je ta vaše hodina, a moc temnosti."]]},{"title":"Petr zapírá Ježíše","range":"Lk 22,54–62","thoughts":[],"verses":[[54,"javše ho, vedli, a uvedli do domu nejvyššího kněze {biskupova}. Petr pak šel za ním zdaleka."],[55,"když zanítili oheň u prostřed síně, a posadili se kolem, sedl Petr mezi ně."],[56,"když uvidělši ho jedna děvečka, an sedí u ohně, a pilně naň pohleděvši, řekla: A tento byl s ním."],[57,"On pak zapřel ho, řka: Ženo, neznám ho."],[58,"po malé chvíli jiný, vida ho, řekl: A ty z nich jsi. Petr pak řekl: Ó člověče, nejsem."],[59,"potom asi po jedné hodině jiný potvrzoval, řka: V pravdě i tento s ním byl, nebo také Galilejský je."],[60,"řekl Petr: Člověče, nevím, co pravíš. A hned, když on ještě mluvil, kohout zazpíval."],[61,"obrátiv se Pán, pohleděl na Petra. A rozpomenul se Petr na slovo Páně, jak mu byl řekl: Že prvé než kohout zazpívá, třikrát mne zapříš."],[62,"vyšel ven Petr, plakal hořce."]]},{"title":"Ježíš před radou","range":"Lk 22,63–71","thoughts":[],"verses":[[63,"Muži pak ti, kteříž drželi Ježíše, posmívali se mu, tepouce ho."],[64,"zakrývajíce ho, bili ho v tvář, a tázali se ho, řkouce: Prorokuj, kdo je, kterýž tebe udeřil?"],[65,"jiného mnoho, rouhajíce se, mluvili proti němu."],[66,"když byl den, sešli se starší lidu a přední kněží {biskupové} a zákonníci, a vedli ho do rady své,"],[67,"Řkouce: Jsi-li ty Kristus? Pověz nám. A dí jim: Povím-li vám, nikoli neuvěříte."],[68,"pakli se vás co otíži, neodpovíte mi, ani nepropustíte."],[69,"Od této chvíle Syn člověka sedne na pravici moci Boží."],[70,"řekli všichni: Potom jsi ty Syn Boží? On pak řekl jim: Vy říkáte, nebo já jsem."],[71,"oni řekli: Což ještě potřebujeme svědectví? Však jsme sami slyšeli z úst jeho."]]}];

LUKE_SECTIONS["23"] = [{"title":"Ježíš před Pilátem","range":"Lk 23,1–5","thoughts":[],"verses":[[1,"Tehdy vstalši všechno množství jich, vedli ho ku Pilátovi."],[2,"počali naň žalovati, řkouce: Tohoto jsme nalezli, an převrací lid, a brání daně dávati císaři, pravě se býti Kristem králem."],[3,"Pilát pak otázal se ho, řka: Jsi-liž ty král ten Židovský? A on odpověděv, řekl mu: Ty pravíš."],[4,"dí Pilát předním kněžím {biskupům} a zástupům: Žádné viny nenalézám na tomto člověku."],[5,"Oni pak více se silili, řkouce: Bouříť lid, uče po všem Judstvu, počav od Galilee až sem."]]},{"title":"Ježíš před Herodem","range":"Lk 23,6–12","thoughts":[],"verses":[[6,"Pilát uslyšav o Galilei, otázal se, byl-li by člověk Galilejský."],[7,"když zvěděl, že by byl z panství Heródesova, poslal ho k Heródesovi, kterýž také v Jeruzalémě byl v ty dni."],[8,"Heródes pak když uviděl Ježíše, zradoval se velmi. Protože dávno žádal viděti ho, proto že mnoho o něm slýchal, a nadál se, že nějaký div uzří od něj učiněný."],[9,"tázal se ho mnohými řečmi, ale on mu nic neodpovídal."],[10,"Stáli pak přední kněží {biskupové} a zákonníci, tuze na něj žalujíce."],[11,"pohrdna jím Heródes s svým rytířstvem, a naposmívav se mu, oblékl ho v oděv bílé, i odeslal zase ku Pilátovi."],[12,"učiněni jsou přátelé Pilát s Heródesem v ten den. Protože před tím nepřátelé byli vespolek."]]},{"title":"Ježíš odsouzen k smrti","range":"Lk 23,13–25","thoughts":[],"verses":[[13,"Pilát pak svolav přední kněží {biskupy} a úřadné osoby i lid,"],[14,"Řekl jim: Dali jste mi tohoto člověka, jako by lid odvracel, a aj, já před vámi vyptávaje se ho, žádné viny jsem nenalezl na tom člověku v tom, což na něj žalujete."],[15,"Ano ani Heródes; nebo odeslal jsem vás k němu, a aj, nic hodného smrti nestalo se mu."],[16,"Protože potrestaje, propustím ho."],[17,"Musil pak propouštívati jim jednoho v svátek."],[18,"Protož zkřiklo spolu všechno množství, řkouce: Zahlaď tohoto, a propusť nám Barabáše."],[19,"Kterýž byl pro bouřku nějakou v městě učiněnou a pro vraždu vsazen do žaláře."],[20,"Pilát znovu mluvil, chtěje propustiti Ježíše."],[21,"Oni pak vždy volali, řkouce: Ukřižuj ho, ukřižuj."],[22,"on potřetí řekl jim: Což pak zlého udělal tento? Žádné příčiny smrti nenalezl jsem na něm. Protož potresce, propustím ho."],[23,"Oni pak předce dotírali křikem velikým, žádajíce, aby byl ukřižován. A rozmáhali se hlasové jejich i předních kněží {biskupů}."],[24,"Pilát pak přisoudil, aby se naplnila žádost jejich."],[25,"propustil jim toho, kterýž pro bouřku a vraždu vsazen byl do žaláře, za nějž prosili, ale Ježíše vydal k vůli jejich."]]},{"title":"Cesta na Golgotu","range":"Lk 23,26–32","thoughts":[],"verses":[[26,"když ho vedli, chytivše Šimona nějakého Cyrenenského, jdoucího s pole, vložili na něj kříž, aby nesl za Ježíšem."],[27,"šlo za ním veliké množství lidu i žen, kteréž plakaly a kvílily ho."],[28,"obrátiv se k nim Ježíš, dí: Dcery Jeruzalémské, neplačte nade mnou, ale raději samy nad sebou plačte a nad svými dětmi."],[29,"Protože aj, dnové jdou, v nichž řeknou: Blahoslavené neplodné, a břicha, kteráž nerodila, a prsy, kteréž nekrmily."],[30,"Tehdyť počnou říci k horám: Padněte na nás, a pahrbkům: Přikrejte nás."],[31,"Protože poněvadž na zeleném dřevě toto se děje, i co pak bude na suchém?"],[32,"Vedeni pak byli i jiní dva zločinci, aby spolu s ním byli ukřižováni."]]},{"title":"Ukřižování","range":"Lk 23,33–43","thoughts":[],"verses":[[33,"když přišli na místo, kteréž slove popravištné, tu ho ukřižovali, i ty zločince, jednoho na pravici, druhého pak na levici."],[34,"Ježíš řekl: Otče, odpusť jim, neboť nevědí, co činí. A rozdělivše oděv jeho, metali los."],[35,"stál lid, řeklvaje se. A posmívali se mu knížata {biskupové} s nimi, řkouce: Jinýmť spomáhal, nechať pomůže sám sobě, jestliže on je Kristus, ten Boží zvolený."],[36,"Posmívali se pak mu i žoldnéři, přistupujíce a octa podávajíce mu,"],[37,"říkajíce: Jsi-li ty král ten Židovský, spomoziž sám sobě."],[38,"byl také i nápis napsaný nad ním, literami Řeckými a Latinskými a Židovskými: Tento je král Židovský."],[39,"Jeden pak z těch zločinců, kteříž s ním viseli, rouhal se mu, řka: Jsi-li ty Kristus, spomoziž sobě i nám."],[40,"odpověděv druhý, trestal ho, řka: Ani ty se Boha nebojíš, ješto jsi v témž potupení?"],[41,"my zajisté spravedlivě, nebo hodnou pomstu za skutky své béřeme, ale tento nic zlého neučinil."],[42,"dí Ježíšovi: Pane, rozpomeň se na mne, když přijdeš do království svého."],[43,"řekl mu Ježíš: Amen říkám tobě, dnes budeš se mnou v ráji."]]},{"title":"Ježíšova smrt","range":"Lk 23,44–49","thoughts":[],"verses":[[44,"bylo okolo hodiny šesté. A stala se tma po vší zemi až do hodiny deváté."],[45,"zatmělo se slunce, a opona chrámová roztrhla se napoly."],[46,"zvolav Ježíš hlasem velikým, řekl: Otče, v ruce tvé poroučím ducha svého. A to pověděv, umřel."],[47,"když viděl centurio, co se stalo, velebil Boha, řka: Jistě člověk tento spravedlivý byl."],[48,"všichni zástupové, přítomní tomu divadlu, hledíce na to, co se dálo, tepouce prsy své, navracovali se."],[49,"Stáli pak všichni známí jeho zdaleka, hledíce na to, i ženy, kteréž byly přišly za ním z Galilee."]]},{"title":"Ježíšův pohřeb","range":"Lk 23,50–56","thoughts":[],"verses":[[50,"aj, muž jménem Jozef, jeden z úřadu, muž dobrý a spravedlivý,"],[51,"Kterýž byl nepovolil radě a skutku jejich, z Arimatie města Judského, kterýž také očekával království Božího;"],[52,"Ten přistoupiv ku Pilátovi, vyprosil tělo Ježíšovo."],[53,"složiv je, obvinul v kment, a pochoval je v hrobě vytesaném, v kterémž ještě nikdy nebyl žádný pochován."],[54,"byl den připravování, a sobota se začínala."],[55,"Šedše pak také za ním ženy, kteréž byly s Ježíšem přišly z Galilee, pohleděly na hrob, a jak pochováno bylo tělo jeho."],[56,"Vrátivše se pak, připravily vonné věci a masti, ale v sobotu odpočinuly, podlé přikázaní."]]}];

LUKE_SECTIONS["24"] = [{"title":"Prázdný hrob","range":"Lk 24,1–12","thoughts":[],"verses":[[1,"Prvního pak dne po sobotě velmi ráno šly k hrobu, nesouce vonné věci, kteréž byly připravily, a některé jiné s nimi."],[2,"nalezly kámen odvalený od hrobu."],[3,"všelše, nenalezly těla Pána Ježíše."],[4,"stalo se, když ony se toho užasly, aj, muži dva postavili se podlé nich v rouše stkvoucím."],[5,"Když se pak ony bály, a sklonily tváři své k zemi, řekli jim: Co hledáte živého s mrtvými?"],[6,"Neníť ho tuto, ale vstalť je. Rozpomeňte se, jak mluvil vám, když ještě v Galilei byl,"],[7,"Řka: Že Syn člověka musí vydán býti v ruce hříšných lidí, a ukřižován býti, a v třetí den z mrtvých vstáti."],[8,"rozpomenuly se na slova jeho."],[9,"navrátivše se od hrobu, zvěstovaly to všechno těm jedenácti i jiným všechněm."],[10,"Byly pak Maria Magdaléna a Johanna a Maria Jakubova, a jiné s nimi, kteréž vypravovaly to apoštolům."],[11,"Ale oni měli za bláznovství slova jejich, a nevěřili jim."],[12,"Petr vstal, běžel k hrobu, a pohleděv do něj, uviděl prostěradla, ana sama leží. A odšel, divě se sám v sobě, co se to stalo."]]},{"title":"Cesta do Emauz","range":"Lk 24,13–35","thoughts":[],"verses":[[13,"aj, dva z nich šli toho dne do městečka, kteréž bylo vzdálí od Jeruzaléma honů šedesáte, muž jméno Emaus."],[14,"rozmlouvali vespolek o těch všech věcech, kteréž se byly staly."],[15,"stalo se, když rozmlouvali, a sebe se otazovali, že i Ježíš, přiblíživ se, šel s nimi."],[16,"Ale oči jejich držány byly, aby ho nepoznali."],[17,"řekl jim: Které jsou to věci, o nichž rozjímáte vespolek, když šli, a jste smutní?"],[18,"odpověděv jeden, kterémuž jméno Kleofáš, řekl mu: Ty sám jsi z příchozích do Jeruzaléma, ještos nezvěděl, co se stalo v něm těchto dnů?"],[19,"Kterýmž on řekl: A co? Oni pak řekli mu: O Ježíšovi Nazaretském, kterýž byl muž prorok, mocný v slovu i v skutku, před Bohem i přede vším lidem,"],[20,"Totiž jak ho vydali přední kněží {biskupové} a knížata naše na odsouzení k smrti, i ukřižovali ho."],[21,"My pak jsme se nadáli, že by on měl vykoupiti Izraele. Ale nyní tomu všemu třetí den je dnes, jakž se to stalo."],[22,"Ale i ženy některé z našich zděsily nás, kteréž ráno byly u hrobu."],[23,"nenalezše tělo jeho, přišly, říkáce, že také vidění andělské viděly, kteříž praví, že by živ byl."],[24,"chodili někteří z našich k hrobu, a nalezli tak, jakž pravily ženy, ale jeho neviděli."],[25,"on řekl jim: Ó nesmyslní a zpozdilí srdcem k věření všemu tomu, což mluvili proroci."],[26,"Zdaliž nemusil těch věcí trpěti Kristus a vjíti v slávu svou?"],[27,"počav od Mojžíše a všech proroků, vykládal jim všechna ta písma, kteráž o něm byla."],[28,"přiblížili se k městečku, do kteréhož šli, a on potrh se, jako by chtěl dále jíti."],[29,"Ale přinutili ho, řkouce: Zůstaň s námi, nebo se již připozdívá, a den se nachýlil. A všel, aby s nimi zůstal."],[30,"stalo se, když seděl s nimi za stolem, vzav chléb, dobrořečil, a láměl, podával jim."],[31,"otevříny jsou oči jejich, a poznali ho. On pak odnesl se od nich."],[32,"řekli vespolek: Zdaliž srdce naše v nás nehořelo, když mluvil nám na cestě, a když otvíral nám písma?"],[33,"vstalše v tu hodinu, vrátili se do Jeruzaléma, a nalezli shromážděných těch jedenácte, a ty, kteříž s nimi byli,"],[34,"Ani praví: Že vstal Pán právě, a ukázal se Šimonovi."],[35,"vypravovali oni také to, co se stalo na cestě, a jak ho poznali v lámání chleba."]]},{"title":"Ježíš se ukazuje učedníkům","range":"Lk 24,36–49","thoughts":[],"verses":[[36,"když oni o tom rozmlouvali, postavil se Ježíš u prostřed nich, a řekl jim: Pokoj vám."],[37,"Oni pak zhrozivše se a přestrašeni když bylše, domnívali se, že by ducha viděli."],[38,"dí jim: Co se strašíte, a proč myšlení vstupují na srdce vaše?"],[39,"Vizte ruce mé i nohy mé, já zajisté jsem ten. Dotýkejte se mne a vizte; neboť duchtěla a kostí nemá, jako mne vidíte míti."],[40,"pověděv to, ukázal jim ruce i nohy."],[41,"Když pak oni ještě nevěřili pro radost, ale divili se, řekl jim: Máte-li tu co k jídlu?"],[42,"oni podali mu kusu ryby pečené a plástu strdi."],[43,"vzav, pojedl před nimi,"],[44,"řekl jim: Tatoť jsou slova, kteráž jsem mluvil vám, ještě když byl s vámi: Že se musí naplniti všechno, což psáno je v zákoně Mojžíšově a v prorocích i v žalmích o mně."],[45,"otevřel jim mysl, aby rozuměli písmům."],[46,"řekl jim: Takť je psáno, a tak musil Kristus trpěti, a třetího dne z mrtvých vstáti,"],[47,"aby bylo kázáno ve jménu jeho pokání a odpuštění hříchů mezi všemi národy, počna od Jeruzaléma."],[48,"Vy pak jste svědkové toho."],[49,"aj, já pošli zaslíbení Otce svého na vás. Vy pak čekejte v městě Jeruzalémě, dokudž nebudete oblečeni mocí s výsosti."]]},{"title":"Nanebevstoupení","range":"Lk 24,50–53","thoughts":[],"verses":[[50,"vyvedl je ven až do Betany, a pozdvih rukou svých, dal jim požehnání."],[51,"stalo se, když jim žehnal, bral se od nich, a nesen je do nebe."],[52,"oni poklonivše se mu, navrátili se do Jeruzaléma s radostí velikou."],[53,"byli vždycky v chrámě, chválíce a dobrořečíce Boha. Amen."]]}];

